/* lights-at-night */
sec('Rules of the Air','Lights on aircraft',[dzF('Reading another aircraft\'s lights at night','<g class="pdg"><path d="M170 200V48M170 200L62 132M170 200L278 132M170 200L74 52M170 200L266 52" stroke="var(--line)" stroke-width="1" fill="none" stroke-dasharray="2 3"/><g transform="translate(170 212) rotate(0) scale(1.5)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/><circle cx="-10.3" cy="-3.3" r="1.9" fill="#e0262b" stroke="var(--surface)" stroke-width=".5"/><circle cx="10.3" cy="-3.3" r="1.9" fill="#2fa84f" stroke="var(--surface)" stroke-width=".5"/><circle cx="0" cy="10.6" r="1.6" fill="#ffffff" stroke="var(--ink)" stroke-width=".4"/></g><text x="146" y="228" class="d1" text-anchor="end">You</text><g transform="translate(170 36) rotate(180) scale(1.4)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/><circle cx="-10.3" cy="-3.3" r="1.9" fill="#e0262b" stroke="var(--surface)" stroke-width=".5"/><circle cx="10.3" cy="-3.3" r="1.9" fill="#2fa84f" stroke="var(--surface)" stroke-width=".5"/><circle cx="0" cy="10.6" r="1.6" fill="#ffffff" stroke="var(--ink)" stroke-width=".4"/></g><text x="170" y="64" class="d1" text-anchor="middle" style="fill:var(--bad)">Red and green: head-on</text><text x="170" y="76" class="d2" text-anchor="middle">both turn right</text><g transform="translate(62 128) rotate(90) scale(1.4)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/><circle cx="-10.3" cy="-3.3" r="1.9" fill="#e0262b" stroke="var(--surface)" stroke-width=".5"/><circle cx="10.3" cy="-3.3" r="1.9" fill="#2fa84f" stroke="var(--surface)" stroke-width=".5"/><circle cx="0" cy="10.6" r="1.6" fill="#ffffff" stroke="var(--ink)" stroke-width=".4"/></g><text x="62" y="104" class="d1" text-anchor="middle" style="fill:var(--good)">Green on your left</text><text x="62" y="154" class="d2" text-anchor="middle">it gives way to you;</text><text x="62" y="164" class="d2" text-anchor="middle">hold heading and speed</text><g transform="translate(278 128) rotate(-90) scale(1.4)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/><circle cx="-10.3" cy="-3.3" r="1.9" fill="#e0262b" stroke="var(--surface)" stroke-width=".5"/><circle cx="10.3" cy="-3.3" r="1.9" fill="#2fa84f" stroke="var(--surface)" stroke-width=".5"/><circle cx="0" cy="10.6" r="1.6" fill="#ffffff" stroke="var(--ink)" stroke-width=".4"/></g><text x="278" y="104" class="d1" text-anchor="middle" style="fill:var(--bad)">Red on your right</text><text x="278" y="154" class="d2" text-anchor="middle">it is on your right:</text><text x="278" y="164" class="d2" text-anchor="middle">you give way</text><g transform="translate(56 40) rotate(200) scale(1.3)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/><circle cx="-10.3" cy="-3.3" r="1.9" fill="#e0262b" stroke="var(--surface)" stroke-width=".5"/><circle cx="10.3" cy="-3.3" r="1.9" fill="#2fa84f" stroke="var(--surface)" stroke-width=".5"/><circle cx="0" cy="10.6" r="1.6" fill="#ffffff" stroke="var(--ink)" stroke-width=".4"/></g><text x="56" y="16" class="d1" text-anchor="middle" style="fill:var(--good)">Red to red: safe</text><g transform="translate(284 40) rotate(160) scale(1.3)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/><circle cx="-10.3" cy="-3.3" r="1.9" fill="#e0262b" stroke="var(--surface)" stroke-width=".5"/><circle cx="10.3" cy="-3.3" r="1.9" fill="#2fa84f" stroke="var(--surface)" stroke-width=".5"/><circle cx="0" cy="10.6" r="1.6" fill="#ffffff" stroke="var(--ink)" stroke-width=".4"/></g><text x="284" y="16" class="d1" text-anchor="middle" style="fill:var(--good)">Green to green: safe</text><text x="276" y="208" class="d2" text-anchor="middle">White only: it is</text><text x="276" y="218" class="d2" text-anchor="middle">flying away from you</text></g>','Your red is on your left, your green on your right. Matching colours on the same side mean the paths will not cross; red facing green means risk. Check the bearing as well.',340,240)]);
/* constant-bearing */
sec('Rules of the Air','Collision avoidance',[dzF('Constant bearing means a collision course','<g class="pdg"><path d="M250 204V40" stroke="var(--accent)" stroke-width="1.2" fill="none" stroke-dasharray="3 3"/><path d="M70 40H250" stroke="var(--ink-2)" stroke-width="1.2" fill="none" stroke-dasharray="3 3"/><circle cx="250" cy="40" r="6" fill="var(--bad)" opacity=".85"/><text x="262" y="36" class="d1" style="fill:var(--bad)">collision</text><path d="M250 178L110 50" stroke="var(--good)" stroke-width="1.2" fill="none"/><g transform="translate(250 190) rotate(0) scale(1.2)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><g transform="translate(100 40) rotate(90) scale(1.2)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><text x="100" y="24" class="d2" text-anchor="middle">t1</text><text x="266" y="194" class="d2">t1</text><path d="M250 160A18 18 0 0 0 237.3 165.3" fill="none" stroke="var(--mid)" stroke-width="1.4"/><path d="M250 128L160 50" stroke="var(--good)" stroke-width="1.2" fill="none"/><g transform="translate(250 140) rotate(0) scale(1.2)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><g transform="translate(150 40) rotate(90) scale(1.2)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><text x="150" y="24" class="d2" text-anchor="middle">t2</text><text x="266" y="144" class="d2">t2</text><path d="M250 110A18 18 0 0 0 237.3 115.3" fill="none" stroke="var(--mid)" stroke-width="1.4"/><path d="M250 78L210 50" stroke="var(--good)" stroke-width="1.2" fill="none"/><g transform="translate(250 90) rotate(0) scale(1.2)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><g transform="translate(200 40) rotate(90) scale(1.2)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><text x="200" y="24" class="d2" text-anchor="middle">t3</text><text x="266" y="94" class="d2">t3</text><path d="M250 60A18 18 0 0 0 237.3 65.3" fill="none" stroke="var(--mid)" stroke-width="1.4"/><text x="214" y="122" class="d1" text-anchor="end" style="paint-order:stroke;stroke:var(--ch-land);stroke-width:3px;stroke-linejoin:round;fill:var(--mid)">same angle</text><text x="214" y="134" class="d2" text-anchor="end" style="paint-order:stroke;stroke:var(--ch-land);stroke-width:3px;stroke-linejoin:round">every time</text><g transform="translate(14 118)"><path d="M0 6Q60-6 120 6L114 74H6Z" fill="var(--ch-wt)" stroke="var(--ink)" stroke-width="1.4"/><path d="M6 52H114L114 74H6Z" fill="var(--ch-l1)"/><path d="M3 50H117" stroke="var(--good)" stroke-width="1.4"/><path d="M60 2V74" stroke="var(--ink)" stroke-width="2.2"/><g transform="translate(34 36)"><path d="M-9 0H7L10-3L12-1L9 2H-9Z" fill="var(--ink)"/><path d="M-4 0L-1-6H2L1 0Z" fill="var(--ink)"/></g><circle cx="34" cy="36" r="13" fill="none" stroke="var(--bad)" stroke-width="1.2" stroke-dasharray="3 2"/></g><text x="74" y="108" class="d2" text-anchor="middle">Your view at t1, t2 and t3</text><text x="74" y="206" class="d1" text-anchor="middle" style="font-size:9px">It stays still in your windscreen</text></g>','If another aircraft keeps the same relative bearing while its range closes, you will collide. In the windscreen it does not move, it just grows. Change heading or height to break it.',320,214)]);
/* join-the-pattern */
sec('Rules of the Air','Flights near an aerodrome',[dzF('Join the pattern: all turns to the left','<g class="pdg"><rect x="70" y="142" width="180" height="16" fill="var(--rwy)"/><path d="M86 150H234" stroke="#fff" stroke-width="1" fill="none" stroke-dasharray="8 6"/><text x="78" y="154" class="mono" text-anchor="middle" style="fill:#fff;font-size:8px">09</text><text x="242" y="154" class="mono" text-anchor="middle" style="fill:#fff;font-size:8px">27</text><path d="M250 150H282Q296 150 296 136V62Q296 48 282 48H38Q24 48 24 62V136Q24 150 38 150H70" stroke="var(--accent)" stroke-width="1.8" fill="none" stroke-dasharray="6 3"/><path d="M0 0L-8 -4L-8 4Z" fill="var(--accent)" transform="translate(276 150) rotate(0)"/><path d="M0 0L-8 -4L-8 4Z" fill="var(--accent)" transform="translate(296 98) rotate(-90)"/><path d="M0 0L-8 -4L-8 4Z" fill="var(--accent)" transform="translate(156 48) rotate(180)"/><path d="M0 0L-8 -4L-8 4Z" fill="var(--accent)" transform="translate(24 104) rotate(90)"/><path d="M0 0L-8 -4L-8 4Z" fill="var(--accent)" transform="translate(56 150) rotate(0)"/><g transform="translate(160 150) rotate(90) scale(1.0)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><text x="268" y="172" class="d2" text-anchor="middle">upwind</text><text x="288" y="100" class="d2" text-anchor="end">crosswind</text><text x="160" y="40" class="d2" text-anchor="middle">downwind</text><text x="32" y="100" class="d2">base</text><text x="40" y="172" class="d2" text-anchor="middle">final</text><g transform="translate(150 80) rotate(180)"><path d="M0 0V16" stroke="var(--ink-2)" stroke-width="1.2"/><path d="M0 0L18 2.5V5.5L0 8Z" fill="#e8742c"/><path d="M6 1V7M12 2V6" stroke="#fff" stroke-width="1.6"/></g><text x="140" y="104" class="d2" text-anchor="middle">windsock</text><path d="M240 90H202" stroke="var(--ink-2)" stroke-width="1.6" fill="none"/><path d="M0 0L-8 -4L-8 4Z" fill="var(--ink-2)" transform="translate(198 90) rotate(180)"/><text x="220" y="82" class="d2" text-anchor="middle">wind</text><text x="160" y="128" class="d1" text-anchor="middle" style="font-size:9px">Left-hand unless signals say otherwise</text><text x="160" y="194" class="d2" text-anchor="middle">Straight in: long final 8 to 4 NM, final within 4 NM</text></g>','Conform to the circuit other traffic is flying, or keep clear of it. Take off and land into wind. On a straight-in approach report long final at 8 NM and final at 4 NM.',320,204)]);
/* no-runway */
sec('Rules of the Air','Order of landing',[dzF('No runway: keep earlier traffic on your left','<g class="pdg"><rect x="30" y="26" width="260" height="142" rx="4" fill="var(--ch-l1)" stroke="var(--ch-tx)" stroke-width=".8"/><text x="40" y="40" class="d2">grass landing area</text><g transform="translate(262 8) rotate(0)"><path d="M0 0V16" stroke="var(--ink-2)" stroke-width="1.2"/><path d="M0 0L18 2.5V5.5L0 8Z" fill="#e8742c"/><path d="M6 1V7M12 2V6" stroke="#fff" stroke-width="1.6"/></g><text x="256" y="18" class="d2" text-anchor="end">wind from the west</text><path d="M300 72H202" stroke="var(--accent)" stroke-width="1.2" fill="none"/><path d="M174 72H156" stroke="var(--accent)" stroke-width="1.6" fill="none" stroke-dasharray="5 3"/><path d="M0 0L-8 -4L-8 4Z" fill="var(--accent)" transform="translate(150 72) rotate(180)"/><g transform="translate(186 72) rotate(-90) scale(1.3)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><text x="196" y="58" class="d1" text-anchor="middle" style="fill:var(--accent)">Landing: leaves it on its left</text><path d="M300 128H132" stroke="var(--ink-2)" stroke-width="1.2" fill="none"/><path d="M106 128Q84 128 84 150" stroke="var(--ink-2)" stroke-width="1.6" fill="none" stroke-dasharray="5 3"/><path d="M0 0L-8 -4L-8 4Z" fill="var(--ink-2)" transform="translate(84 156) rotate(90)"/><g transform="translate(118 128) rotate(-90) scale(1.3)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><text x="200" y="118" class="d1" text-anchor="middle">Already landed: turns left</text><text x="200" y="146" class="d2" text-anchor="middle">once sure it will not get in the way</text><text x="160" y="186" class="d1" text-anchor="middle" style="font-size:9px">Taking off: leave earlier departures on your left too</text><text x="160" y="198" class="d2" text-anchor="middle">After landing, clear the landing area as soon as possible</text></g>','Where take-offs and landings are not confined to a runway, newer traffic stays to the right of older traffic, and turns on the landing area are to the left.',320,206)]);
/* line-feature */
sec('Rules of the Air','Radio in the ATZ',[dzF('Following a line feature: keep it on your left','<g class="pdg"><path d="M10 112L310 88" stroke="var(--ink-2)" stroke-width="3" fill="none"/><path d="M12 108.0V116.0M22 107.2V115.2M32 106.4V114.4M42 105.6V113.6M52 104.8V112.8M62 104.0V112.0M72 103.2V111.2M82 102.4V110.4M92 101.6V109.6M102 100.8V108.8M112 100.0V108.0M122 99.2V107.2M132 98.4V106.4M142 97.6V105.6M152 96.8V104.8M162 96.0V104.0M172 95.2V103.2M182 94.4V102.4M192 93.6V101.6M202 92.8V100.8M212 92.0V100.0M222 91.2V99.2M232 90.4V98.4M242 89.6V97.6M252 88.8V96.8M262 88.0V96.0M272 87.2V95.2M282 86.4V94.4M292 85.6V93.6M302 84.8V92.8M312 84.0V92.0" stroke="var(--ink-2)" stroke-width="1.2" fill="none"/><text x="16" y="130" class="d2">railway, road, canal or coast</text><path d="M20 152H96" stroke="var(--accent)" stroke-width="1.2" fill="none" stroke-dasharray="4 3"/><g transform="translate(110 150) rotate(90) scale(1.4)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M126 150L164 149" stroke="var(--accent)" stroke-width="1.6" fill="none"/><path d="M0 0L-8 -4L-8 4Z" fill="var(--accent)" transform="translate(170 149) rotate(-1)"/><path d="M300 52H222" stroke="var(--accent)" stroke-width="1.2" fill="none" stroke-dasharray="4 3"/><g transform="translate(208 52) rotate(-90) scale(1.4)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M192 52L156 53" stroke="var(--accent)" stroke-width="1.6" fill="none"/><path d="M0 0L-8 -4L-8 4Z" fill="var(--accent)" transform="translate(150 53) rotate(179)"/><text x="60" y="176" class="d1">Heading east: line on the left</text><text x="262" y="30" class="d1" text-anchor="end">Heading west: line on the left</text><text x="160" y="196" class="d2" text-anchor="middle">Both keep to the right, so they pass apart</text></g>','No longer a legal requirement under SERA, but the CAA strongly recommends it. In controlled airspace follow ATC instead.',320,204)]);
/* low-flying-minima */
sec('Rules of the Air','Low flying prohibitions',[dzF('Low flying minima (UK, day)','<g class="pdg"><path d="M0 170H320V200H0Z" fill="var(--ch-l1)"/><path d="M10 170V150h12v20M28 170V140h10v30M44 170V156h16v14" fill="var(--ch-tn)" stroke="var(--ch-tnl)"/><g fill="var(--ch-tn)" stroke="var(--ch-tnl)"><path d="M180 170V146h14v24M200 170V132h10v38M214 170V150h20v20M240 170V138h12v32M258 170V152h18v18M282 170V128h8v42"/></g><g transform="translate(70 108) scale(-1.0 1.0)"><path d="M16.6-6.7L27.4-15.8Q28.4-16.3 29.4-15.8L30.8-4Z" fill="var(--accent)"/><path d="M23.5-3.1L33.6-2.7Q34.3-2.2 33.6-1.8L23.5-1.4Z" fill="var(--accent)"/><path d="M-28.4-1.6C-28.4-3.2-27.5-4.2-26-4.5L-17-5.6L-13.4-6.1L-7.1-9.6C-5.6-10.1-3-10.2 0-10.2L6.5-10C8.5-9.8 9.8-9.1 11-8L27-4.6L31.6-3.8L31.7-2.6L26-1.6L12 0.6C5 1.8-2 2.6-8 2.8L-20 2.6C-24 2.4-26.5 1.6-27.5 0.6C-28.2 0-28.4-0.6-28.4-1.6Z" fill="var(--accent)"/><path d="M-28.3-3.3Q-31.6-1.6-28.3 0.1Z" fill="var(--accent)"/><path d="M-14.5 1.6Q-15.6 3.7-12.4 3.9L8.2 3.4Q10.2 3.1 10.2 1.6Z" fill="var(--accent)"/><path d="M-29.5-1.8L-27.3-10.5Q-26.7-11.1-26.8-10.2L-28.9-1.4ZM-29.3-1.4L-31.6 7.3Q-32.2 7.9-32.1 7L-30.1-1.8Z" fill="var(--accent)"/><path d="M-12.1-6.3L-7.3-9.1H-5.4V-6.3Z" fill="var(--surface)" opacity=".85"/><rect x="-4.2" y="-9.1" width="6" height="2.8" rx=".6" fill="var(--surface)" opacity=".85"/><path d="M3-9.1H6.2C8-9 9-8.5 9.8-7.7L9.2-6.3H3Z" fill="var(--surface)" opacity=".85"/></g><circle cx="70" cy="108" r="54" fill="none" stroke="var(--accent)" stroke-dasharray="4 3"/><path d="M70 116V156" stroke="var(--accent)" stroke-width="1.2" fill="none"/><path d="M0 0L-7.0 -3.5L-7.0 3.5Z" fill="var(--accent)" transform="translate(70 161) rotate(90)"/><text x="76" y="142" class="d1" style="paint-order:stroke;stroke:var(--ch-land);stroke-width:3px;stroke-linejoin:round">500 ft</text><text x="70" y="22" class="d1" text-anchor="middle">Anywhere (UK, day):</text><text x="70" y="34" class="d2" text-anchor="middle">500 ft from any person,</text><text x="70" y="44" class="d2" text-anchor="middle">vehicle, vessel or structure</text><g transform="translate(236 72) scale(-1.0 1.0)"><path d="M16.6-6.7L27.4-15.8Q28.4-16.3 29.4-15.8L30.8-4Z" fill="var(--accent)"/><path d="M23.5-3.1L33.6-2.7Q34.3-2.2 33.6-1.8L23.5-1.4Z" fill="var(--accent)"/><path d="M-28.4-1.6C-28.4-3.2-27.5-4.2-26-4.5L-17-5.6L-13.4-6.1L-7.1-9.6C-5.6-10.1-3-10.2 0-10.2L6.5-10C8.5-9.8 9.8-9.1 11-8L27-4.6L31.6-3.8L31.7-2.6L26-1.6L12 0.6C5 1.8-2 2.6-8 2.8L-20 2.6C-24 2.4-26.5 1.6-27.5 0.6C-28.2 0-28.4-0.6-28.4-1.6Z" fill="var(--accent)"/><path d="M-28.3-3.3Q-31.6-1.6-28.3 0.1Z" fill="var(--accent)"/><path d="M-14.5 1.6Q-15.6 3.7-12.4 3.9L8.2 3.4Q10.2 3.1 10.2 1.6Z" fill="var(--accent)"/><path d="M-29.5-1.8L-27.3-10.5Q-26.7-11.1-26.8-10.2L-28.9-1.4ZM-29.3-1.4L-31.6 7.3Q-32.2 7.9-32.1 7L-30.1-1.8Z" fill="var(--accent)"/><path d="M-12.1-6.3L-7.3-9.1H-5.4V-6.3Z" fill="var(--surface)" opacity=".85"/><rect x="-4.2" y="-9.1" width="6" height="2.8" rx=".6" fill="var(--surface)" opacity=".85"/><path d="M3-9.1H6.2C8-9 9-8.5 9.8-7.7L9.2-6.3H3Z" fill="var(--surface)" opacity=".85"/></g><path d="M168 128H306" stroke="var(--bad)" stroke-width="1" fill="none" stroke-dasharray="3 3"/><path d="M240 82V120" stroke="var(--bad)" stroke-width="1.2" fill="none"/><path d="M0 0L-7.0 -3.5L-7.0 3.5Z" fill="var(--bad)" transform="translate(240 126) rotate(90)"/><text x="246" y="106" class="d1" style="fill:var(--bad)">1,000 ft</text><path d="M176 186H304" stroke="var(--ink-2)" stroke-width="1" fill="none"/><path d="M176 182V190M304 182V190" stroke="var(--ink-2)" stroke-width="1" fill="none"/><text x="240" y="197" class="d2" text-anchor="middle">highest obstacle within 600 m</text><text x="240" y="22" class="d1" text-anchor="middle">Congested area:</text><text x="240" y="34" class="d2" text-anchor="middle">1,000 ft above the highest obstacle</text><text x="240" y="44" class="d2" text-anchor="middle">and able to land clear</text></g>','Except for take-off and landing, keep 500 ft from people and things. Over towns and assemblies, 1,000 ft above the highest obstacle within 600 m.',320,202)]);
/* congested-area */
sec('Rules of the Air','Low flying prohibitions',[dzF('Congested area: 1,000 ft and able to land clear','<g class="pdg"><path d="M0 182H320V212H0Z" fill="var(--ch-l1)"/><path d="M70 182H74V176H104V182H106V168H120V182H122V160H142V182H146V142H164V182H166V124H182V182H184V148H206V182H208V162H226V182H228V170H254V182H256V176H276V182Z" fill="var(--ch-tn)" stroke="var(--ch-tnl)" stroke-width=".8"/><path d="M173 124V108" stroke="var(--ch-tnl)" stroke-width="1.6" fill="none"/><text x="20" y="200" class="d2">open fields</text><text x="300" y="200" class="d2" text-anchor="end">fields</text><g transform="translate(174 30) scale(-1.0 1.0)"><path d="M16.6-6.7L27.4-15.8Q28.4-16.3 29.4-15.8L30.8-4Z" fill="var(--accent)"/><path d="M23.5-3.1L33.6-2.7Q34.3-2.2 33.6-1.8L23.5-1.4Z" fill="var(--accent)"/><path d="M-28.4-1.6C-28.4-3.2-27.5-4.2-26-4.5L-17-5.6L-13.4-6.1L-7.1-9.6C-5.6-10.1-3-10.2 0-10.2L6.5-10C8.5-9.8 9.8-9.1 11-8L27-4.6L31.6-3.8L31.7-2.6L26-1.6L12 0.6C5 1.8-2 2.6-8 2.8L-20 2.6C-24 2.4-26.5 1.6-27.5 0.6C-28.2 0-28.4-0.6-28.4-1.6Z" fill="var(--accent)"/><path d="M-28.3-3.3Q-31.6-1.6-28.3 0.1Z" fill="var(--accent)"/><path d="M-14.5 1.6Q-15.6 3.7-12.4 3.9L8.2 3.4Q10.2 3.1 10.2 1.6Z" fill="var(--accent)"/><path d="M-29.5-1.8L-27.3-10.5Q-26.7-11.1-26.8-10.2L-28.9-1.4ZM-29.3-1.4L-31.6 7.3Q-32.2 7.9-32.1 7L-30.1-1.8Z" fill="var(--accent)"/><path d="M-12.1-6.3L-7.3-9.1H-5.4V-6.3Z" fill="var(--surface)" opacity=".85"/><rect x="-4.2" y="-9.1" width="6" height="2.8" rx=".6" fill="var(--surface)" opacity=".85"/><path d="M3-9.1H6.2C8-9 9-8.5 9.8-7.7L9.2-6.3H3Z" fill="var(--surface)" opacity=".85"/></g><path d="M150 108H200" stroke="var(--bad)" stroke-width="1" fill="none" stroke-dasharray="3 3"/><path d="M174 40V100" stroke="var(--bad)" stroke-width="1.4" fill="none"/><path d="M0 0L-7.0 -3.5L-7.0 3.5Z" fill="var(--bad)" transform="translate(174 106) rotate(90)"/><text x="180" y="78" class="d1" style="paint-order:stroke;stroke:var(--ch-land);stroke-width:3px;stroke-linejoin:round;fill:var(--bad)">1,000 ft</text><path d="M174 40L100 182M174 40L248 182" stroke="var(--accent)" stroke-width="1" fill="none" stroke-dasharray="2 3"/><path d="M100 194H248M100 190V198M248 190V198" stroke="var(--accent)" stroke-width="1" fill="none"/><text x="174" y="207" class="d2" text-anchor="middle">highest obstacle within 600 m</text><path d="M168 40L40 176" stroke="var(--good)" stroke-width="1.4" fill="none" stroke-dasharray="6 4"/><text x="16" y="140" class="d1" style="paint-order:stroke;stroke:var(--ch-land);stroke-width:3px;stroke-linejoin:round;fill:var(--good)">glide range</text><text x="16" y="151" class="d2" style="paint-order:stroke;stroke:var(--ch-land);stroke-width:3px;stroke-linejoin:round">reaches open ground</text></g>','Over a city, town or settlement fly at least 1,000 ft above the highest obstacle within 600 m, and high enough to glide clear if the engine stops. Landing clear is the pilot\'s job, not ATC\'s.',320,214)]);
/* 500ft-rule */
sec('Rules of the Air','Low flying prohibitions',[dzF('The 500 ft rule: EASA and UK compared','<g class="pdg"><path d="M0 172H320V200H0Z" fill="var(--ch-l1)"/><path d="M160 14V196" stroke="var(--line)" stroke-width="1" fill="none"/><text x="80" y="22" class="d1" text-anchor="middle">EASA, and UK at night</text><text x="80" y="34" class="d2" text-anchor="middle">500 ft above the ground or the</text><text x="80" y="44" class="d2" text-anchor="middle">highest obstacle within 150 m</text><path d="M116 172V140h8v32Z" fill="var(--ch-tn)" stroke="var(--ch-tnl)"/><path d="M28 84H152" stroke="var(--bad)" stroke-width="1" fill="none" stroke-dasharray="3 3"/><g transform="translate(70 70) scale(-0.9 0.9)"><path d="M16.6-6.7L27.4-15.8Q28.4-16.3 29.4-15.8L30.8-4Z" fill="var(--accent)"/><path d="M23.5-3.1L33.6-2.7Q34.3-2.2 33.6-1.8L23.5-1.4Z" fill="var(--accent)"/><path d="M-28.4-1.6C-28.4-3.2-27.5-4.2-26-4.5L-17-5.6L-13.4-6.1L-7.1-9.6C-5.6-10.1-3-10.2 0-10.2L6.5-10C8.5-9.8 9.8-9.1 11-8L27-4.6L31.6-3.8L31.7-2.6L26-1.6L12 0.6C5 1.8-2 2.6-8 2.8L-20 2.6C-24 2.4-26.5 1.6-27.5 0.6C-28.2 0-28.4-0.6-28.4-1.6Z" fill="var(--accent)"/><path d="M-28.3-3.3Q-31.6-1.6-28.3 0.1Z" fill="var(--accent)"/><path d="M-14.5 1.6Q-15.6 3.7-12.4 3.9L8.2 3.4Q10.2 3.1 10.2 1.6Z" fill="var(--accent)"/><path d="M-29.5-1.8L-27.3-10.5Q-26.7-11.1-26.8-10.2L-28.9-1.4ZM-29.3-1.4L-31.6 7.3Q-32.2 7.9-32.1 7L-30.1-1.8Z" fill="var(--accent)"/><path d="M-12.1-6.3L-7.3-9.1H-5.4V-6.3Z" fill="var(--surface)" opacity=".85"/><rect x="-4.2" y="-9.1" width="6" height="2.8" rx=".6" fill="var(--surface)" opacity=".85"/><path d="M3-9.1H6.2C8-9 9-8.5 9.8-7.7L9.2-6.3H3Z" fill="var(--surface)" opacity=".85"/></g><path d="M120 86V132" stroke="var(--bad)" stroke-width="1.2" fill="none"/><path d="M0 0L-7.0 -3.5L-7.0 3.5Z" fill="var(--bad)" transform="translate(120 138) rotate(90)"/><text x="126" y="114" class="d1" style="fill:var(--bad)">500 ft</text><path d="M70 160H114M70 156V164M114 156V164" stroke="var(--ink-2)" stroke-width="1" fill="none"/><path d="M70 80V154" stroke="var(--ink-2)" stroke-width="0.8" fill="none" stroke-dasharray="2 3"/><text x="92" y="154" class="d2" text-anchor="middle">150 m</text><text x="240" y="22" class="d1" text-anchor="middle">UK by day</text><text x="240" y="34" class="d2" text-anchor="middle">500 ft from any person,</text><text x="240" y="44" class="d2" text-anchor="middle">vehicle, vessel or structure</text><path d="M250 168l14 0l-3 4h-10Z" fill="var(--ink)"/><path d="M257 166V146l8 18Z" fill="var(--ink)"/><path d="M200 172A57 57 0 0 1 314 172" fill="var(--bad)" opacity=".12" stroke="var(--bad)" stroke-dasharray="4 3"/><g transform="translate(200 100) scale(-0.9 0.9)"><path d="M16.6-6.7L27.4-15.8Q28.4-16.3 29.4-15.8L30.8-4Z" fill="var(--accent)"/><path d="M23.5-3.1L33.6-2.7Q34.3-2.2 33.6-1.8L23.5-1.4Z" fill="var(--accent)"/><path d="M-28.4-1.6C-28.4-3.2-27.5-4.2-26-4.5L-17-5.6L-13.4-6.1L-7.1-9.6C-5.6-10.1-3-10.2 0-10.2L6.5-10C8.5-9.8 9.8-9.1 11-8L27-4.6L31.6-3.8L31.7-2.6L26-1.6L12 0.6C5 1.8-2 2.6-8 2.8L-20 2.6C-24 2.4-26.5 1.6-27.5 0.6C-28.2 0-28.4-0.6-28.4-1.6Z" fill="var(--accent)"/><path d="M-28.3-3.3Q-31.6-1.6-28.3 0.1Z" fill="var(--accent)"/><path d="M-14.5 1.6Q-15.6 3.7-12.4 3.9L8.2 3.4Q10.2 3.1 10.2 1.6Z" fill="var(--accent)"/><path d="M-29.5-1.8L-27.3-10.5Q-26.7-11.1-26.8-10.2L-28.9-1.4ZM-29.3-1.4L-31.6 7.3Q-32.2 7.9-32.1 7L-30.1-1.8Z" fill="var(--accent)"/><path d="M-12.1-6.3L-7.3-9.1H-5.4V-6.3Z" fill="var(--surface)" opacity=".85"/><rect x="-4.2" y="-9.1" width="6" height="2.8" rx=".6" fill="var(--surface)" opacity=".85"/><path d="M3-9.1H6.2C8-9 9-8.5 9.8-7.7L9.2-6.3H3Z" fill="var(--surface)" opacity=".85"/></g><path d="M216 108L236 122" stroke="var(--bad)" stroke-width="1.2" fill="none"/><path d="M0 0L-7.0 -3.5L-7.0 3.5Z" fill="var(--bad)" transform="translate(240 125) rotate(36)"/><text x="268" y="100" class="d1" text-anchor="middle" style="fill:var(--bad)">500 ft bubble</text><text x="240" y="190" class="d2" text-anchor="middle">lower over open ground is allowed</text></g>','EASA sets a height above the surface. The UK day rule is a 500 ft bubble around people and things instead. Take-off and landing are exempt from both.',320,200)]);
/* open-air-assemblies */
sec('Rules of the Air','Open-air assemblies',[dzF('Open-air assemblies of more than 1,000 people','<g class="pdg"><ellipse cx="110" cy="160" rx="96" ry="30" fill="none" stroke="var(--mid)" stroke-dasharray="5 4"/><ellipse cx="110" cy="158" rx="40" ry="13" fill="var(--surface-2)" stroke="var(--ink)" stroke-width="1.4"/><ellipse cx="110" cy="156" rx="26" ry="7" fill="var(--ch-l1)" stroke="var(--ink-2)"/><path d="M70 158V164A40 13 0 0 0 150 164V158" fill="none" stroke="var(--ink)" stroke-width="1.4"/><text x="110" y="186" class="d2" text-anchor="middle">over 1,000 people</text><g transform="translate(110 28) scale(-0.9 0.9)"><path d="M16.6-6.7L27.4-15.8Q28.4-16.3 29.4-15.8L30.8-4Z" fill="var(--accent)"/><path d="M23.5-3.1L33.6-2.7Q34.3-2.2 33.6-1.8L23.5-1.4Z" fill="var(--accent)"/><path d="M-28.4-1.6C-28.4-3.2-27.5-4.2-26-4.5L-17-5.6L-13.4-6.1L-7.1-9.6C-5.6-10.1-3-10.2 0-10.2L6.5-10C8.5-9.8 9.8-9.1 11-8L27-4.6L31.6-3.8L31.7-2.6L26-1.6L12 0.6C5 1.8-2 2.6-8 2.8L-20 2.6C-24 2.4-26.5 1.6-27.5 0.6C-28.2 0-28.4-0.6-28.4-1.6Z" fill="var(--accent)"/><path d="M-28.3-3.3Q-31.6-1.6-28.3 0.1Z" fill="var(--accent)"/><path d="M-14.5 1.6Q-15.6 3.7-12.4 3.9L8.2 3.4Q10.2 3.1 10.2 1.6Z" fill="var(--accent)"/><path d="M-29.5-1.8L-27.3-10.5Q-26.7-11.1-26.8-10.2L-28.9-1.4ZM-29.3-1.4L-31.6 7.3Q-32.2 7.9-32.1 7L-30.1-1.8Z" fill="var(--accent)"/><path d="M-12.1-6.3L-7.3-9.1H-5.4V-6.3Z" fill="var(--surface)" opacity=".85"/><rect x="-4.2" y="-9.1" width="6" height="2.8" rx=".6" fill="var(--surface)" opacity=".85"/><path d="M3-9.1H6.2C8-9 9-8.5 9.8-7.7L9.2-6.3H3Z" fill="var(--surface)" opacity=".85"/></g><path d="M110 40V134" stroke="var(--bad)" stroke-width="1.4" fill="none"/><path d="M0 0L-7.0 -3.5L-7.0 3.5Z" fill="var(--bad)" transform="translate(110 140) rotate(90)"/><text x="116" y="76" class="d1" style="fill:var(--bad)">1,000 ft above the</text><text x="116" y="88" class="d2">highest obstacle</text><text x="116" y="98" class="d2">within 600 m, or</text><text x="116" y="108" class="d2">enough to land clear</text><text x="116" y="118" class="d2">if that is higher</text><g transform="translate(282 100) scale(0.8 0.8)"><path d="M16.6-6.7L27.4-15.8Q28.4-16.3 29.4-15.8L30.8-4Z" fill="var(--accent)"/><path d="M23.5-3.1L33.6-2.7Q34.3-2.2 33.6-1.8L23.5-1.4Z" fill="var(--accent)"/><path d="M-28.4-1.6C-28.4-3.2-27.5-4.2-26-4.5L-17-5.6L-13.4-6.1L-7.1-9.6C-5.6-10.1-3-10.2 0-10.2L6.5-10C8.5-9.8 9.8-9.1 11-8L27-4.6L31.6-3.8L31.7-2.6L26-1.6L12 0.6C5 1.8-2 2.6-8 2.8L-20 2.6C-24 2.4-26.5 1.6-27.5 0.6C-28.2 0-28.4-0.6-28.4-1.6Z" fill="var(--accent)"/><path d="M-28.3-3.3Q-31.6-1.6-28.3 0.1Z" fill="var(--accent)"/><path d="M-14.5 1.6Q-15.6 3.7-12.4 3.9L8.2 3.4Q10.2 3.1 10.2 1.6Z" fill="var(--accent)"/><path d="M-29.5-1.8L-27.3-10.5Q-26.7-11.1-26.8-10.2L-28.9-1.4ZM-29.3-1.4L-31.6 7.3Q-32.2 7.9-32.1 7L-30.1-1.8Z" fill="var(--accent)"/><path d="M-12.1-6.3L-7.3-9.1H-5.4V-6.3Z" fill="var(--surface)" opacity=".85"/><rect x="-4.2" y="-9.1" width="6" height="2.8" rx=".6" fill="var(--surface)" opacity=".85"/><path d="M3-9.1H6.2C8-9 9-8.5 9.8-7.7L9.2-6.3H3Z" fill="var(--surface)" opacity=".85"/></g><path d="M262 110L214 148" stroke="var(--mid)" stroke-width="1.4" fill="none" stroke-dasharray="5 3"/><path d="M0 0L-7.0 -3.5L-7.0 3.5Z" fill="var(--mid)" transform="translate(209 152) rotate(141)"/><text x="276" y="134" class="d1" text-anchor="middle" style="fill:var(--mid)">No take-off or</text><text x="276" y="147" class="d1" text-anchor="middle" style="fill:var(--mid)">landing within</text><text x="276" y="160" class="d1" text-anchor="middle" style="fill:var(--mid)">1,000 m</text><text x="266" y="178" class="d2" text-anchor="middle">unless at an aerodrome</text><text x="266" y="190" class="d2" text-anchor="middle">or with permission</text></g>','UK: written CAA permission is needed to fly lower. The 1,000 m take-off and landing ban has exceptions at aerodromes (CAA procedures) and at other sites with the organiser\'s permission.',320,200)]);
/* intercepted-what-to-do */
sec('Rules of the Air','Interception: what to do (AIP ENR 1.12)',[dzF('If you are intercepted','<g class="pdg"><circle cx="20" cy="26" r="9" fill="var(--bad)"/><text x="20" y="29.2" class="n" text-anchor="middle">1</text><rect x="38" y="11" width="56" height="30" rx="6" fill="var(--surface)" stroke="var(--line)" stroke-width="1"/><text x="104" y="25" class="d1">Follow the interceptor\'s signals</text><text x="104" y="36" class="d2">precisely, and stay calm</text><circle cx="20" cy="68" r="9" fill="var(--bad)"/><text x="20" y="71.2" class="n" text-anchor="middle">2</text><rect x="38" y="53" width="56" height="30" rx="6" fill="var(--surface)" stroke="var(--line)" stroke-width="1"/><text x="104" y="67" class="d1">Tell the ATS unit you are working</text><text x="104" y="78" class="d2">if you can</text><circle cx="20" cy="110" r="9" fill="var(--bad)"/><text x="20" y="113.2" class="n" text-anchor="middle">3</text><rect x="38" y="95" width="56" height="30" rx="6" fill="var(--surface)" stroke="var(--line)" stroke-width="1"/><text x="104" y="109" class="d1">Call on 121.50 MHz</text><text x="104" y="120" class="d2">your callsign and the nature of your flight</text><circle cx="20" cy="152" r="9" fill="var(--bad)"/><text x="20" y="155.2" class="n" text-anchor="middle">4</text><rect x="38" y="137" width="56" height="30" rx="6" fill="var(--surface)" stroke="var(--line)" stroke-width="1"/><text x="104" y="151" class="d1">Squawk 7700</text><text x="104" y="162" class="d2">unless the ATS unit tells you otherwise</text><g transform="translate(52 31) rotate(90) scale(0.85)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><g transform="translate(79 20) rotate(90) scale(0.85)"><path d="'+ACPATH+'" fill="var(--bad)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M64 14q-3 4 0 8" stroke="var(--bad)" stroke-width="1.1" fill="none"/><path d="M94 14q3 4 0 8" stroke="var(--bad)" stroke-width="1.1" fill="none"/><path d="M66 81V60M60 81H72M61 64l5-4 5 4" stroke="var(--ink)" stroke-width="1.4" fill="none"/><path d="M74 62q4 4 0 8M78 59q7 7 0 14" stroke="var(--accent)" stroke-width="1.1" fill="none"/><text x="66" y="114" class="mono" text-anchor="middle">121.50</text><rect x="44" y="144" width="44" height="14" rx="3" fill="var(--ink)" stroke="var(--ink)" stroke-width="1"/><text x="66" y="154.5" class="mono" text-anchor="middle" style="fill:var(--surface);font-size:10px">7700</text><rect x="10" y="182" width="300" height="30" rx="6" fill="var(--surface)" stroke="var(--bad)" stroke-width="1.4"/><text x="160" y="195" class="d1" text-anchor="middle" style="font-size:8.6px">Conflicting instructions from ATC? Ask at once,</text><text x="160" y="206" class="d1" text-anchor="middle" style="font-size:8.6px">but obey the interceptor\'s visual signals.</text></g>','Do all four straight away. Avoid hand signals: they are easily misread. Report any interception abroad to the CAA.',320,222)]);
/* interceptor-signals */
sec('Rules of the Air','Interception signals',[dzF('The interceptor\'s signals to you','<g class="pdg"><path d="M8 90H312" stroke="var(--ch-tx)" stroke-width="0.8" fill="none" opacity=".45"/><path d="M8 172H312" stroke="var(--ch-tx)" stroke-width="0.8" fill="none" opacity=".45"/><path d="M22 60H60" stroke="var(--accent)" stroke-width="1" fill="none" stroke-dasharray="3 2"/><g transform="translate(66 60) rotate(90) scale(0.95)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><g transform="translate(98 40) rotate(90) scale(0.95)"><path d="'+ACPATH+'" fill="var(--bad)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M83 34q-3 4 0 8" stroke="var(--bad)" stroke-width="1.1" fill="none"/><path d="M113 34q3 4 0 8" stroke="var(--bad)" stroke-width="1.1" fill="none"/><path d="M110 40Q132 40 132 18" stroke="var(--bad)" stroke-width="1.4" fill="none" stroke-dasharray="4 2"/><path d="M0 0L-7.0 -3.5L-7.0 3.5Z" fill="var(--bad)" transform="translate(132 16) rotate(-90)"/><text x="66" y="80" class="d2" text-anchor="middle">you</text><text x="98" y="22" class="d2" text-anchor="middle">interceptor</text><text x="150" y="22" class="d1">“Follow me”</text><text x="150" y="35" class="d2"><tspan class="b">Interceptor:</tspan> rocks its wings from slightly above</text><text x="150" y="45" class="d2">and ahead (normally on your left), then makes</text><text x="150" y="55" class="d2">a slow level turn, normally to the left.</text><text x="150" y="65" class="d2"><tspan class="b">You:</tspan> rock your wings and follow. At night also</text><text x="150" y="75" class="d2">flash your nav lights at irregular intervals.</text><path d="M22 142H140" stroke="var(--accent)" stroke-width="1" fill="none" stroke-dasharray="3 2"/><g transform="translate(50 142) rotate(90) scale(0.95)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><text x="132" y="154" class="d2" text-anchor="end">your line of flight</text><g transform="translate(84 124) rotate(90) scale(0.95)"><path d="'+ACPATH+'" fill="var(--bad)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M96 124Q120 124 122 102" stroke="var(--bad)" stroke-width="1.6" fill="none"/><path d="M0 0L-7.0 -3.5L-7.0 3.5Z" fill="var(--bad)" transform="translate(122 99) rotate(-90)"/><text x="128" y="114" class="d2">climbing turn</text><text x="128" y="124" class="d2">of 90° or more</text><text x="196" y="104" class="d1">“You may proceed”</text><text x="196" y="117" class="d2"><tspan class="b">Interceptor:</tspan> abrupt break-away,</text><text x="196" y="127" class="d2">a climbing turn of 90° or more</text><text x="196" y="137" class="d2">without crossing your line</text><text x="196" y="147" class="d2">of flight.</text><text x="196" y="157" class="d2"><tspan class="b">You:</tspan> rock your wings.</text><rect x="36" y="212" width="80" height="8" fill="var(--rwy)"/><path d="M122 216Q128 186 76 186Q24 186 24 216Q24 242 60 242H92" stroke="var(--bad)" stroke-width="1.3" fill="none" stroke-dasharray="4 2"/><path d="M0 0L-7.0 -3.5L-7.0 3.5Z" fill="var(--bad)" transform="translate(98 242) rotate(0)"/><g transform="translate(90 216) rotate(90) scale(0.95)"><path d="'+ACPATH+'" fill="var(--bad)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><text x="150" y="186" class="d1">“Land at this aerodrome”</text><text x="150" y="199" class="d2"><tspan class="b">Interceptor:</tspan> circles, lowers its gear and</text><text x="150" y="209" class="d2">overflies the runway in the landing direction</text><text x="150" y="219" class="d2">(steady landing lights at night).</text><text x="150" y="229" class="d2"><tspan class="b">You:</tspan> lower gear if you can, follow, and land if,</text><text x="150" y="239" class="d2">after overflying the runway, it looks safe.</text></g>','Too slow to keep up? The interceptor flies racetracks and rocks its wings each time it passes you.',320,258)]);
/* your-signals */
sec('Rules of the Air','Interception signals',[dzF('Your signals to the interceptor','<g class="pdg"><rect x="10" y="30" width="170" height="40" fill="var(--mid)" opacity=".12"/><path d="M10 30H180M10 70H180" stroke="var(--mid)" stroke-width="0.9" fill="none" stroke-dasharray="4 3"/><text x="14" y="26" class="d2">2,000 ft aal</text><text x="14" y="80" class="d2">1,000 ft aal</text><rect x="40" y="104" width="110" height="5" fill="var(--rwy)"/><path d="M10 109H180" stroke="var(--ink-2)" stroke-width="1" fill="none"/><g transform="translate(96 52) scale(-0.9 0.9)"><path d="M16.6-6.7L27.4-15.8Q28.4-16.3 29.4-15.8L30.8-4Z" fill="var(--accent)"/><path d="M23.5-3.1L33.6-2.7Q34.3-2.2 33.6-1.8L23.5-1.4Z" fill="var(--accent)"/><path d="M-28.4-1.6C-28.4-3.2-27.5-4.2-26-4.5L-17-5.6L-13.4-6.1L-7.1-9.6C-5.6-10.1-3-10.2 0-10.2L6.5-10C8.5-9.8 9.8-9.1 11-8L27-4.6L31.6-3.8L31.7-2.6L26-1.6L12 0.6C5 1.8-2 2.6-8 2.8L-20 2.6C-24 2.4-26.5 1.6-27.5 0.6C-28.2 0-28.4-0.6-28.4-1.6Z" fill="var(--accent)"/><path d="M-28.3-3.3Q-31.6-1.6-28.3 0.1Z" fill="var(--accent)"/><path d="M-14.5 1.6Q-15.6 3.7-12.4 3.9L8.2 3.4Q10.2 3.1 10.2 1.6Z" fill="var(--accent)"/><path d="M-29.5-1.8L-27.3-10.5Q-26.7-11.1-26.8-10.2L-28.9-1.4ZM-29.3-1.4L-31.6 7.3Q-32.2 7.9-32.1 7L-30.1-1.8Z" fill="var(--accent)"/><path d="M-12.1-6.3L-7.3-9.1H-5.4V-6.3Z" fill="var(--surface)" opacity=".85"/><rect x="-4.2" y="-9.1" width="6" height="2.8" rx=".6" fill="var(--surface)" opacity=".85"/><path d="M3-9.1H6.2C8-9 9-8.5 9.8-7.7L9.2-6.3H3Z" fill="var(--surface)" opacity=".85"/></g><path d="M62 50H40" stroke="var(--accent)" stroke-width="1" fill="none" stroke-dasharray="3 2"/><path d="M136 50h14" stroke="var(--accent)" stroke-width="1.2" fill="none"/><path d="M0 0L-7.0 -3.5L-7.0 3.5Z" fill="var(--accent)" transform="translate(154 50) rotate(0)"/><text x="190" y="18" class="d1">“Aerodrome inadequate”</text><text x="190" y="31" class="d2">Raise gear if possible while</text><text x="190" y="41" class="d2">passing over the runway between</text><text x="190" y="51" class="d2">1,000 and 2,000 ft above</text><text x="190" y="61" class="d2">aerodrome level, and keep circling.</text><path d="M8 122H312" stroke="var(--ch-tx)" stroke-width="0.8" fill="none" opacity=".45"/><text x="10" y="142" class="d1">“I cannot comply”</text><text x="10" y="153" class="d2">all lights on and off,</text><text x="10" y="163" class="d2">regular intervals</text><rect x="122" y="146" width="10" height="12" rx="1.5" fill="var(--mid)"/><rect x="142" y="146" width="10" height="12" rx="1.5" fill="var(--mid)"/><rect x="162" y="146" width="10" height="12" rx="1.5" fill="var(--mid)"/><rect x="182" y="146" width="10" height="12" rx="1.5" fill="var(--mid)"/><rect x="202" y="146" width="10" height="12" rx="1.5" fill="var(--mid)"/><rect x="222" y="146" width="10" height="12" rx="1.5" fill="var(--mid)"/><rect x="242" y="146" width="10" height="12" rx="1.5" fill="var(--mid)"/><rect x="262" y="146" width="10" height="12" rx="1.5" fill="var(--mid)"/><rect x="282" y="146" width="10" height="12" rx="1.5" fill="var(--mid)"/><path d="M118 159H308" stroke="var(--ink-2)" stroke-width="0.8" fill="none"/><text x="10" y="184" class="d1">“I am in distress”</text><text x="10" y="195" class="d2">all lights on and off,</text><text x="10" y="205" class="d2">irregular intervals</text><rect x="122" y="188" width="4" height="12" rx="1.5" fill="var(--mid)"/><rect x="132" y="188" width="14" height="12" rx="1.5" fill="var(--mid)"/><rect x="150" y="188" width="4" height="12" rx="1.5" fill="var(--mid)"/><rect x="172" y="188" width="8" height="12" rx="1.5" fill="var(--mid)"/><rect x="185" y="188" width="3" height="12" rx="1.5" fill="var(--mid)"/><rect x="192" y="188" width="16" height="12" rx="1.5" fill="var(--mid)"/><rect x="220" y="188" width="5" height="12" rx="1.5" fill="var(--mid)"/><rect x="233" y="188" width="9" height="12" rx="1.5" fill="var(--mid)"/><rect x="245" y="188" width="4" height="12" rx="1.5" fill="var(--mid)"/><path d="M118 201H308" stroke="var(--ink-2)" stroke-width="0.8" fill="none"/><text x="122" y="214" class="d2">time</text><path d="M0 0L-6 -3L-6 3Z" fill="var(--ink-2)" transform="translate(306 201) rotate(0)"/><rect x="10" y="222" width="300" height="22" rx="6" fill="var(--surface)" stroke="var(--line)" stroke-width="1"/><text x="160" y="236" class="d2" text-anchor="middle">The interceptor answers both with a break-away climbing turn: “understood”.</text></g>','“Cannot comply” must look different from ordinary flashing lights, so switch every light fully on and off.',320,252)]);
