/* direction-of-take-off-and-landing */
sec('Aerodromes','Signals area: direction',[dzF('Direction of take-off and landing','<g class="pdg"><rect x="8" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="16" y="14" width="80" height="50" rx="3" fill="#2b2f36"/><path d="M36 22H43V56H36Z" fill="#f4f1e6"/><path d="M43 36H84V42H43Z" fill="#f4f1e6"/><text x="56" y="75" text-anchor="middle" class="d2">Land and take off</text><text x="56" y="86" text-anchor="middle" class="d2">towards the cross-arm</text><rect x="112" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="120" y="14" width="80" height="50" rx="3" fill="#2b2f36"/><path d="M140 22H147V56H140Z" fill="#f4f1e6"/><path d="M147 36H188V42H147Z" fill="#f4f1e6"/><circle cx="131" cy="39" r="4.5" fill="#f4f1e6"/><text x="160" y="75" text-anchor="middle" class="d2">Disc: directions</text><text x="160" y="86" text-anchor="middle" class="d2">may not coincide</text><rect x="216" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="224" y="14" width="80" height="50" rx="3" fill="var(--surface)"/><path d="M252 60H276" stroke="var(--ink-2)" stroke-width="2"/><path d="M257 60L264 17L271 60" stroke="var(--ink-2)" stroke-width=".8" fill="none"/><path d="M264 60V17" stroke="var(--ink)" stroke-width="1.8"/><circle cx="258" cy="27" r="5" fill="#111"/><text x="264" y="75" text-anchor="middle" class="d2">Black ball on the</text><text x="264" y="86" text-anchor="middle" class="d2">mast: the same</text><path d="M60.0 104.0L30.4 104.0" stroke="var(--accent)" stroke-width="1.6" fill="none"/><path d="M22.0 104.0L30.4 107.8L30.4 100.2Z" fill="var(--accent)"/><text x="64" y="108" class="d2">landing direction for the T</text></g>','Land and take off parallel with the shaft of the T, towards the cross-arm, unless ATC say otherwise. A disc at the head of the T, or a black ball on the mast, means landing and take-off may be in different directions.',320,116)]);
/* use-hard-surfaces-only */
sec('Aerodromes','Signals area: direction',[dzF('Use hard surfaces only','<g class="pdg"><rect x="8" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="16" y="14" width="80" height="50" rx="3" fill="#2b2f36"/><circle cx="32" cy="39" r="11" fill="#f4f1e6"/><circle cx="80" cy="39" r="11" fill="#f4f1e6"/><path d="M32 36H80V42H32Z" fill="#f4f1e6"/><text x="56" y="75" text-anchor="middle" class="d2">Dumb-bell: taxi on</text><text x="56" y="86" text-anchor="middle" class="d2">hard surfaces only</text><rect x="112" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="120" y="14" width="80" height="50" rx="3" fill="#2b2f36"/><circle cx="136" cy="39" r="11" fill="#f4f1e6"/><circle cx="184" cy="39" r="11" fill="#f4f1e6"/><path d="M136 36H184V42H136Z" fill="#f4f1e6"/><path d="M136 28V50M184 28V50" stroke="#2b2f36" stroke-width="3.5"/><text x="160" y="75" text-anchor="middle" class="d2">Black strips: take off</text><text x="160" y="86" text-anchor="middle" class="d2">and land on a runway</text></g>','Plain dumb-bell: keep to paved, metalled or similar hard surfaces on the ground. Black strips across the discs: runway for take-off and landing, but taxiing need not be on hard surfaces.',320,100)]);
/* light-aircraft-areas */
sec('Aerodromes','Signals area: direction',[dzF('Light aircraft areas','<g class="pdg"><rect x="8" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="16" y="14" width="80" height="50" rx="3" fill="#2b2f36"/><path d="M49 23V53H67" stroke="#f4f1e6" stroke-width="6" fill="none"/><text x="56" y="75" text-anchor="middle" class="d2">White L: light</text><text x="56" y="86" text-anchor="middle" class="d2">aircraft area only</text><rect x="112" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="120" y="14" width="80" height="50" rx="3" fill="#2b2f36"/><path d="M157 19V37H167" stroke="#f4f1e6" stroke-width="3.5" fill="none"/><circle cx="136" cy="49" r="8" fill="#f4f1e6"/><circle cx="184" cy="49" r="8" fill="#f4f1e6"/><path d="M136 46H184V52H136Z" fill="#f4f1e6"/><path d="M156 40V56H167" stroke="#d8312c" stroke-width="3.5" fill="none"/><text x="160" y="75" text-anchor="middle" class="d2">Red L on dumb-bell:</text><text x="160" y="86" text-anchor="middle" class="d2">runway or L area</text></g>','A white L marks part of the manoeuvring area for light aircraft only. A red L on the dumb-bell lets light aircraft use a runway or the white-L area.',320,100)]);
/* a-signals-area-example */
sec('Aerodromes','Signals area: direction',[dzF('A signals area (example)','<g class="pdg"><path d="M20 10H300V170H20Z" fill="#2b2f36"/><path d="M30 20H290V160H30Z" fill="none" stroke="#f4f1e6" stroke-width="3"/><path d="M54 46H118M70 34V58M102 34V58" stroke="#f4f1e6" stroke-width="5"/><path d="M140 40H200" stroke="#f4f1e6" stroke-width="5"/><path d="M212 34H270V128" stroke="#d8312c" stroke-width="8" fill="none"/><path d="M212 34H270V128" stroke="#f2c14a" stroke-width="8" stroke-dasharray="6 6" fill="none"/><path d="M260 126L270 142L280 126Z" fill="#d8312c"/><circle cx="160" cy="100" r="34" fill="#454b55" stroke="#f4f1e6" stroke-width="2"/><path d="M134 96H178V104H134Z" fill="#f4f1e6"/><path d="M178 80H186V120H178Z" fill="#f4f1e6"/><rect x="44" y="110" width="44" height="40" fill="#d8312c"/><path d="M46 148L86 112" stroke="#f2c14a" stroke-width="5"/><text x="86" y="74" text-anchor="middle" class="d2 dk" style="fill:#dfe5f0">gliding</text><text x="170" y="30" text-anchor="middle" class="d2 dk" style="fill:#dfe5f0">dumb-bell (not in use)</text><text x="262" y="84" text-anchor="end" class="d2 dk" style="fill:#dfe5f0">right-hand</text><text x="262" y="95" text-anchor="end" class="d2 dk" style="fill:#dfe5f0">circuit</text><text x="160" y="148" text-anchor="middle" class="d2 dk" style="fill:#dfe5f0">land towards the cross-arm</text><text x="66" y="104" text-anchor="middle" class="d2 dk" style="fill:#dfe5f0">special care</text></g>','A real signals area combines several signals: here special precautions, gliding in progress, a right-hand circuit, and a T showing the landing direction.',320,180)]);
/* right-hand-circuit */
sec('Aerodromes','Signals area: circuit',[dzF('Right-hand circuit','<g class="pdg"><rect x="8" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="16" y="14" width="80" height="50" rx="3" fill="#2b2f36"/><path d="M30 59V25H74" stroke="#d8312c" stroke-width="8" fill="none"/><path d="M30 59V25H74" stroke="#f2c14a" stroke-width="8" stroke-dasharray="5 5" fill="none"/><path d="M72 15L86 25L72 35Z" fill="#d8312c"/><text x="56" y="75" text-anchor="middle" class="d2">Striped arrow round</text><text x="56" y="86" text-anchor="middle" class="d2">the edge, clockwise</text><rect x="112" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="120" y="14" width="80" height="50" rx="3" fill="var(--surface)"/><path d="M148 60H172" stroke="var(--ink-2)" stroke-width="2"/><path d="M153 60L160 17L167 60" stroke="var(--ink-2)" stroke-width=".8" fill="none"/><path d="M160 60V17" stroke="var(--ink)" stroke-width="1.8"/><path d="M161 19h20v14h-20Z" fill="#2f9d4c"/><text x="160" y="75" text-anchor="middle" class="d2">Green flag:</text><text x="160" y="86" text-anchor="middle" class="d2">right-hand circuit</text><rect x="216" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="224" y="14" width="80" height="50" rx="3" fill="var(--surface)"/><path d="M252 60H276" stroke="var(--ink-2)" stroke-width="2"/><path d="M257 60L264 17L271 60" stroke="var(--ink-2)" stroke-width=".8" fill="none"/><path d="M264 60V17" stroke="var(--ink)" stroke-width="1.8"/><path d="M265 19h20v14h-20Z" fill="#d8312c"/><text x="264" y="75" text-anchor="middle" class="d2">Red flag:</text><text x="264" y="86" text-anchor="middle" class="d2">left-hand circuit</text></g>','Turns before landing and after take-off are to the right. Where the circuit changes, the flag shows which: the colours match the nav lights (red port, green starboard).',320,100)]);
/* special-precautions-and-landing-prohibited */
sec('Aerodromes','Signals area: circuit',[dzF('Special precautions and landing prohibited','<g class="pdg"><rect x="8" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="16" y="14" width="80" height="50" rx="3" fill="#2b2f36"/><rect x="36" y="19" width="40" height="40" fill="#d8312c"/><path d="M38 57L74 21" stroke="#f2c14a" stroke-width="5"/><text x="56" y="75" text-anchor="middle" class="d2">One yellow diagonal:</text><text x="56" y="86" text-anchor="middle" class="d2">take special care</text><rect x="112" y="8" width="96" height="84" rx="6" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="120" y="14" width="80" height="50" rx="3" fill="#2b2f36"/><rect x="140" y="19" width="40" height="40" fill="#d8312c"/><path d="M142 57L178 21M142 21L178 57" stroke="#f2c14a" stroke-width="5"/><text x="160" y="75" text-anchor="middle" class="d2">Yellow cross:</text><text x="160" y="86" text-anchor="middle" class="d2">landing prohibited</text></g>','One diagonal: the manoeuvring area is in poor condition, so take care on approach and landing. A diagonal cross: landing is prohibited, probably for a long time.',320,100)]);
/* helicopter-operations-markers */
