/* holding-point-and-holding-position-sign */
sec('Aerodromes','Signals on paved',[dzF('Holding point and holding position sign','<g class="pdg"><path d="M10 22H310V58H10Z" fill="var(--ink-2)"/><text x="160" y="44" text-anchor="middle" class="d1 dk" style="fill:#ffffff">RUNWAY</text><path d="M200 58H240V196H200Z" fill="var(--ink-2)"/><path d="M200 92H240M200 97H240" stroke="#f2c14a" stroke-width="2.4" stroke-dasharray="5 4"/><path d="M200 104H240M200 109H240" stroke="#f2c14a" stroke-width="2.4"/><path d="M220 58V196" stroke="#f2c14a" stroke-width="1.4"/><g transform="translate(220 164) rotate(0) scale(1.2)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M150 118V136M184 118V136" stroke="var(--ink-2)" stroke-width="2"/><rect x="134" y="98" width="20" height="20" fill="#111"/><text x="144" y="112" text-anchor="middle" class="d1 dk" style="fill:#f2c14a">A</text><rect x="154" y="98" width="44" height="20" fill="#d8312c"/><text x="176" y="112" text-anchor="middle" class="d1 dk" style="fill:#ffffff">09-27</text><text x="126" y="90" text-anchor="end" class="d2">holding position sign</text><text x="248" y="92" class="d1">broken lines:</text><text x="248" y="103" class="d2">runway side</text><text x="248" y="120" class="d1">continuous:</text><text x="248" y="131" class="d2">hold here for</text><text x="248" y="142" class="d2">ATC permission</text><text x="192" y="170" text-anchor="end" class="d2">yellow centreline</text><text x="192" y="181" text-anchor="end" class="d2">taxiing out</text></g>','Taxiing out you meet the continuous lines first: stop unless cleared. Leaving the runway you meet the broken lines first and need no clearance. The sign shows taxiway A (yellow on black) and runway 09-27 (white on red, mandatory).',320,204)]);
