/* what-each-class-gives-you */
sec('Air Traffic Services','Services in each airspace class',[dzF('What each class gives you','<g class="pdg"><rect x="8" y="8" width="304" height="22" fill="var(--surface-2)"/><text x="12" y="24" class="d1">Class</text><text x="44" y="24" class="d1">Clearance</text><text x="96" y="24" class="d1">IFR separated from</text><text x="206" y="24" class="d1">VFR get</text><text x="12" y="46" class="d1">A</text><text x="44" y="46" class="d2">all</text><text x="96" y="46" class="d2">all (IFR only)</text><text x="206" y="46" class="d2">(no VFR)</text><rect x="8" y="52" width="304" height="22" fill="var(--surface-2)" opacity=".5"/><text x="12" y="68" class="d1">B</text><text x="44" y="68" class="d2">all</text><text x="96" y="68" class="d2">all</text><text x="206" y="68" class="d2">separation from all</text><text x="12" y="90" class="d1">C</text><text x="44" y="90" class="d2">all</text><text x="96" y="90" class="d2">IFR and VFR</text><text x="206" y="90" class="d2">sep. from IFR; TI on VFR</text><rect x="8" y="96" width="304" height="22" fill="var(--surface-2)" opacity=".5"/><text x="12" y="112" class="d1">D</text><text x="44" y="112" class="d2">all</text><text x="96" y="112" class="d2">IFR</text><text x="206" y="112" class="d2">TI on all; no separation</text><text x="12" y="134" class="d1">E</text><text x="44" y="134" class="d2">IFR only</text><text x="96" y="134" class="d2">IFR</text><text x="206" y="134" class="d2">TI as far as practical</text><rect x="8" y="140" width="304" height="22" fill="var(--surface-2)" opacity=".5"/><text x="12" y="156" class="d1">F</text><text x="44" y="156" class="d2">none</text><text x="96" y="156" class="d2">(advisory)</text><text x="206" y="156" class="d2">service on request</text><text x="12" y="178" class="d1">G</text><text x="44" y="178" class="d2">none</text><text x="96" y="178" class="d2">-</text><text x="206" y="178" class="d2">service on request</text><path d="M8 30H312" stroke="var(--line)" stroke-width="1" fill="none"/></g>','TI = traffic information. In Class D, VFR flights are not separated from anyone: look out. Avoidance advice is available on request in C and D.',320,184)]);
/* who-you-are-talking-to */
sec('Air Traffic Services','AFIS, A/G radio',[dzF('Who you are talking to','<g class="pdg"><rect x="8" y="8" width="304" height="36" rx="4" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="8" y="8" width="6" height="36" fill="var(--accent)"/><text x="22" y="23" class="d1">Tower / Approach / Ground</text><text x="22" y="36" class="d2">ATC</text><text x="170" y="23" class="d2">clearances and instructions</text><rect x="8" y="50" width="304" height="36" rx="4" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="8" y="50" width="6" height="36" fill="var(--good)"/><text x="22" y="65" class="d1">… Information</text><text x="22" y="78" class="d2">AFIS</text><text x="170" y="65" class="d2">information only in the air;</text><text x="170" y="78" class="d2">instructions on the ground</text><rect x="8" y="92" width="304" height="36" rx="4" fill="var(--surface-2)" stroke="var(--line)" stroke-width="1"/><rect x="8" y="92" width="6" height="36" fill="var(--mid)"/><text x="22" y="107" class="d1">… Radio</text><text x="22" y="120" class="d2">A/G</text><text x="170" y="107" class="d2">basic information; no ATC</text><path d="M60 216V160H220V216" fill="var(--accent-soft)" stroke="var(--accent)" stroke-width="1.2"/><path d="M10 216H312" stroke="var(--ink-2)" stroke-width="1.2" fill="none"/><path d="M132 216H148V212H132Z" fill="var(--ink-2)"/><text x="140" y="176" text-anchor="middle" class="d1">Safetycom 135.480</text><text x="140" y="188" text-anchor="middle" class="d2">below 2,000 ft aal</text><text x="140" y="200" text-anchor="middle" class="d2">within 10 nm</text><path d="M140.0 226.0L212.5 226.0" stroke="var(--ink)" stroke-width="1" fill="none"/><path d="M220.0 226.0L212.5 222.6L212.5 229.4Z" fill="var(--ink)"/><text x="232" y="229" class="d2">10 nm</text></g>','The callsign suffix tells you the service. Safetycom is for airfields without their own frequency; keep calls short.',320,236)]);
/* the-four-uk-fis-outside-controlled-airspace */
sec('Air Traffic Services','UK Flight Information Services',[dzF('The four UK FIS outside controlled airspace','<g class="pdg"><rect x="8" y="8" width="304" height="22" fill="var(--surface-2)"/><text x="12" y="24" class="d1"></text><text x="74" y="24" class="d1">Basic</text><text x="140" y="24" class="d1">Traffic</text><text x="194" y="24" class="d1">Deconfl.</text><text x="256" y="24" class="d1">Procedural</text><text x="12" y="46" class="d1">radar?</text><text x="74" y="46" class="d2">no</text><text x="140" y="46" class="d2">yes</text><text x="194" y="46" class="d2">yes</text><text x="256" y="46" class="d2">no</text><rect x="8" y="52" width="304" height="22" fill="var(--surface-2)" opacity=".5"/><text x="12" y="68" class="d1">who</text><text x="74" y="68" class="d2">ctrl or FISO</text><text x="140" y="68" class="d2">controller</text><text x="194" y="68" class="d2">controller</text><text x="256" y="68" class="d2">controller</text><text x="12" y="90" class="d1">flights</text><text x="74" y="90" class="d2">IFR, VFR</text><text x="140" y="90" class="d2">IFR, VFR</text><text x="194" y="90" class="d2">IFR</text><text x="256" y="90" class="d2">IFR</text><rect x="8" y="96" width="304" height="22" fill="var(--surface-2)" opacity=".5"/><text x="12" y="112" class="d1">identified</text><text x="74" y="112" class="d2">maybe</text><text x="140" y="112" class="d2">yes</text><text x="194" y="112" class="d2">yes</text><text x="256" y="112" class="d2">not needed</text><text x="12" y="134" class="d1">traffic info</text><text x="74" y="134" class="d2">not expected</text><text x="140" y="134" class="d2">radar TI</text><text x="194" y="134" class="d2">TI + avoid</text><text x="256" y="134" class="d2">limited</text><rect x="8" y="140" width="304" height="22" fill="var(--surface-2)" opacity=".5"/><text x="12" y="156" class="d1">headings</text><text x="74" y="156" class="d2">-</text><text x="140" y="156" class="d2">sequencing</text><text x="194" y="156" class="d2">to deconflict</text><text x="256" y="156" class="d2">radials, times</text><text x="12" y="178" class="d1">avoidance</text><text x="74" y="178" class="d2" style="fill:var(--bad)">pilot</text><text x="140" y="178" class="d2" style="fill:var(--bad)">pilot</text><text x="194" y="178" class="d2" style="fill:var(--bad)">pilot</text><text x="256" y="178" class="d2" style="fill:var(--bad)">pilot</text><path d="M8 30H312" stroke="var(--line)" stroke-width="1" fill="none"/></g>','Whatever the service, in Class G the pilot is ultimately responsible for collision avoidance and terrain clearance. An alerting service comes with all four.',320,184)]);
/* deconfliction-minima */
sec('Air Traffic Services','Deconfliction Service',[dzF('Deconfliction minima','<g class="pdg"><text x="8" y="16" class="d1">unknown traffic</text><circle cx="80" cy="96" r="60" fill="var(--accent-soft)" stroke="var(--accent)" stroke-dasharray="5 3"/><g transform="translate(80 96) rotate(0) scale(1.2)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M80.0 96.0L131.5 96.0" stroke="var(--ink)" stroke-width="1" fill="none"/><path d="M139.0 96.0L131.5 92.6L131.5 99.4Z" fill="var(--ink)"/><text x="110" y="90" text-anchor="middle" class="d2">5 nm</text><text x="80" y="172" text-anchor="middle" class="d1">5 nm laterally</text><text x="80" y="184" text-anchor="middle" class="d1">OR 3,000 ft vertically</text><text x="170" y="16" class="d1">same controller</text><circle cx="240" cy="96" r="36" fill="var(--good)" opacity=".15" stroke="var(--good)" stroke-dasharray="5 3"/><g transform="translate(240 96) rotate(0) scale(1.2)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M240.0 96.0L267.5 96.0" stroke="var(--ink)" stroke-width="1" fill="none"/><path d="M275.0 96.0L267.5 92.6L267.5 99.4Z" fill="var(--ink)"/><text x="258" y="90" text-anchor="middle" class="d2">3 nm</text><text x="240" y="172" text-anchor="middle" class="d1">3 nm and 1,000 ft</text><text x="240" y="184" text-anchor="middle" class="d2">(some military: 500 ft)</text></g>','Plan view, circles to scale with each other. The minima are aimed at, not guaranteed, and only given at or above the unit\'s terrain safe level.',320,196)]);
