sec('Airspace, ATZ, MATZ and transponders (Skyway Code)','ATZ and aerodromes',[dzF('An ATZ is a cylinder','<g class="pdg"><path d="M0 170H320V200H0Z" fill="var(--ch-l1)"/><ellipse cx="160" cy="168" rx="110" ry="16" fill="var(--ch-l2)" stroke="#c0243a" stroke-width="1.4"/><path d="M50 168V60M270 168V60" stroke="#c0243a" stroke-width="1.4"/><ellipse cx="160" cy="60" rx="110" ry="16" fill="color-mix(in srgb,#c0243a 8%,transparent)" stroke="#c0243a" stroke-width="1.4"/><rect x="130" y="164" width="60" height="6" fill="#555c6b"/><path d="M276.0 166.0L276.0 69.5" stroke="var(--ink)" stroke-width="1" fill="none"/><path d="M276.0 62.0L272.6 69.5L279.4 69.5Z" fill="var(--ink)"/><text x="280" y="112" class="d1" style="font-size:8px;">2,000 ft</text><text x="280" y="123" class="d2" style="font-size:7px;">above the</text><text x="280" y="133" class="d2" style="font-size:7px;">aerodrome</text><path d="M160.0 186.0L262.5 186.0" stroke="var(--ink)" stroke-width="1" fill="none"/><path d="M270.0 186.0L262.5 182.6L262.5 189.4Z" fill="var(--ink)"/><text x="214" y="197" text-anchor="middle" class="d2" style="font-size:7px;">2 NM (2.5 NM if runway over 1,850 m)</text><text x="160" y="30" text-anchor="middle" class="d1" style="font-size:7.6px;">Permission (ATC) or information (AFIS, A/G) before entering</text></g>','Radius depends on the longest runway. Many busy aerodromes have no ATZ, so watch for them anyway.',320,200)]);
/* a-typical-matz */
sec('Airspace, ATZ, MATZ and transponders (Skyway Code)','MATZ',[dzF('A typical MATZ','<g class="pdg"><circle cx="120" cy="100" r="66" fill="color-mix(in srgb,#b0237a 7%,transparent)" stroke="#b0237a" stroke-width="1.6" stroke-dasharray="4 2"/><rect x="186" y="80" width="64" height="40" fill="color-mix(in srgb,#b0237a 7%,transparent)" stroke="#b0237a" stroke-width="1.6" stroke-dasharray="4 2"/><rect x="-10" y="80" width="64" height="40" fill="none"/><circle cx="120" cy="100" r="26" fill="color-mix(in srgb,#c0243a 10%,transparent)" stroke="#c0243a" stroke-width="1.4"/><rect x="104" y="98" width="32" height="4" fill="#555c6b"/><text x="120" y="82" text-anchor="middle" class="d1 dk" style="fill:#c0243a">ATZ</text><text x="218" y="74" text-anchor="middle" class="d2">stub</text><text x="120" y="24" text-anchor="middle" class="d1 dk" style="fill:#b0237a">MATZ: 5 NM radius,</text><text x="120" y="36" text-anchor="middle" class="d2">3,000 ft above the airfield</text><rect x="254" y="20" width="62" height="160" rx="4" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1"/><text x="285" y="38" text-anchor="middle" class="d1">Call</text><text x="285" y="50" text-anchor="middle" class="d2">10 min</text><text x="285" y="61" text-anchor="middle" class="d2">ahead</text><text x="285" y="84" text-anchor="middle" class="d1">Not CAS</text><text x="285" y="96" text-anchor="middle" class="d2">for civil</text><text x="285" y="108" text-anchor="middle" class="d2">aircraft</text><text x="285" y="132" text-anchor="middle" class="d1" style="fill:var(--bad)">Never</text><text x="285" y="144" text-anchor="middle" class="d2">enter the</text><text x="285" y="156" text-anchor="middle" class="d2">ATZ without</text><text x="285" y="168" text-anchor="middle" class="d2">clearance</text></g>','Ask for a MATZ penetration service about 10 minutes ahead. Two calls with no reply: you may enter with caution.',320,200)]);
/* control-zone-and-control-area */
