/* semicircular-cruising-levels-by-magnetic-track */
sec('Altimeter Setting Procedures','The semicircular rule',[dzF('Semicircular cruising levels (by magnetic track)','<g class="pdg"><circle cx="160" cy="104" r="80" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1.2"/><path d="M160 24A80 80 0 0 1 160 184Z" fill="var(--accent-soft)"/><path d="M160 24A80 80 0 0 0 160 184Z" fill="var(--surface-2)"/><path d="M160 18V190" stroke="var(--ink)" stroke-width="1.4" fill="none"/><text x="160" y="14" text-anchor="middle" class="d2">360 / 000°M</text><text x="160" y="202" text-anchor="middle" class="d2">180°M</text><text x="170" y="62" class="d1">000°–179°</text><text x="170" y="82" class="d1">IFR: odd</text><text x="170" y="94" class="d2">FL30, 50, 70</text><text x="170" y="116" class="d1">VFR: odd + 500</text><text x="170" y="128" class="d2">FL35, 55, 75</text><text x="150" y="62" text-anchor="end" class="d1">180°–359°</text><text x="150" y="82" text-anchor="end" class="d1">IFR: even</text><text x="150" y="94" text-anchor="end" class="d2">FL40, 60, 80</text><text x="150" y="116" text-anchor="end" class="d1">VFR: even + 500</text><text x="150" y="128" text-anchor="end" class="d2">FL45, 65, 85</text><path d="M250.0 104.0L287.6 104.0" stroke="var(--accent)" stroke-width="1.6" fill="none"/><path d="M296.0 104.0L287.6 100.2L287.6 107.8Z" fill="var(--accent)"/><text x="300" y="96" text-anchor="end" class="d2">east</text><path d="M70.0 104.0L32.4 104.0" stroke="var(--ink-2)" stroke-width="1.6" fill="none"/><path d="M24.0 104.0L32.4 107.8L32.4 100.2Z" fill="var(--ink-2)"/><text x="20" y="96" class="d2">west</text></g>','East is odd, west is even; VFR adds 500 ft. The rule goes by magnetic track, not heading. Required for IFR; recommended for VFR, which must then set 1013.',320,210)]);
/* from-paris-to-the-uk-on-its-own */
sec('Aviation Law and organisations','International Civil Aviation',[dzF('From Paris to the UK on its own','<g class="pdg"><path d="M20 100H300" stroke="var(--ink)" stroke-width="2" fill="none"/><circle cx="36" cy="100" r="6" fill="var(--accent)" stroke="var(--surface)" stroke-width="2"/><path d="M36 94V70" stroke="var(--ink-2)" stroke-width="1" fill="none"/><text x="36" y="62" text-anchor="middle" class="d3">1919</text><text x="36" y="34" text-anchor="middle" class="d2" style="font-size:7.5px;">Paris</text><text x="36" y="44" text-anchor="middle" class="d2" style="font-size:7.5px;">Convention</text><circle cx="98" cy="100" r="6" fill="var(--accent)" stroke="var(--surface)" stroke-width="2"/><path d="M98 106V130" stroke="var(--ink-2)" stroke-width="1" fill="none"/><text x="98" y="142" text-anchor="middle" class="d3">1944</text><text x="98" y="158" text-anchor="middle" class="d2" style="font-size:7.5px;">Chicago</text><text x="98" y="168" text-anchor="middle" class="d2" style="font-size:7.5px;">Convention</text><circle cx="160" cy="100" r="6" fill="var(--accent)" stroke="var(--surface)" stroke-width="2"/><path d="M160 94V70" stroke="var(--ink-2)" stroke-width="1" fill="none"/><text x="160" y="62" text-anchor="middle" class="d3">1947</text><text x="160" y="34" text-anchor="middle" class="d2" style="font-size:7.5px;">ICAO formed</text><text x="160" y="44" text-anchor="middle" class="d2" style="font-size:7.5px;">in Montreal</text><circle cx="222" cy="100" r="6" fill="var(--accent)" stroke="var(--surface)" stroke-width="2"/><path d="M222 106V130" stroke="var(--ink-2)" stroke-width="1" fill="none"/><text x="222" y="142" text-anchor="middle" class="d3">2021</text><text x="222" y="158" text-anchor="middle" class="d2" style="font-size:7.5px;">UK leaves</text><text x="222" y="168" text-anchor="middle" class="d2" style="font-size:7.5px;">EASA</text><circle cx="278" cy="100" r="6" fill="var(--accent)" stroke="var(--surface)" stroke-width="2"/><path d="M278 94V70" stroke="var(--ink-2)" stroke-width="1" fill="none"/><text x="278" y="62" text-anchor="middle" class="d3">Now</text><text x="278" y="34" text-anchor="middle" class="d2" style="font-size:7.5px;">CAA, ANO and</text><text x="278" y="44" text-anchor="middle" class="d2" style="font-size:7.5px;">assimilated law</text></g>','Paris 1919 set the first principles. Chicago 1944 created the obligations and ICAO followed in 1947. Since 2021 the UK regulates itself.',320,200)]);
/* the-aip-and-the-28-day-airac-cycle */
sec('Aviation Law and organisations','Aeronautical Information Publication',[dzF('The AIP and the 28-day AIRAC cycle','<g class="pdg"><path d="M14 30h52l6 6v104h-58Z" fill="var(--surface)" stroke="var(--accent)" stroke-width="1.6"/><path d="M66 30v6h6" fill="none" stroke="var(--accent)"/><text x="43" y="60" text-anchor="middle" class="d3" style="fill:var(--accent)">GEN</text><text x="43" y="90" text-anchor="middle" class="d2" style="font-size:6.6px;">National rules,</text><text x="43" y="101" text-anchor="middle" class="d2" style="font-size:6.6px;">services, charges</text><path d="M76 30h52l6 6v104h-58Z" fill="var(--surface)" stroke="var(--good)" stroke-width="1.6"/><path d="M128 30v6h6" fill="none" stroke="var(--good)"/><text x="105" y="60" text-anchor="middle" class="d3" style="fill:var(--good)">ENR</text><text x="105" y="90" text-anchor="middle" class="d2" style="font-size:6.6px;">En route rules,</text><text x="105" y="101" text-anchor="middle" class="d2" style="font-size:6.6px;">ATS, warnings</text><path d="M138 30h52l6 6v104h-58Z" fill="var(--surface)" stroke="var(--mid)" stroke-width="1.6"/><path d="M190 30v6h6" fill="none" stroke="var(--mid)"/><text x="167" y="60" text-anchor="middle" class="d3" style="fill:var(--mid)">AD</text><text x="167" y="90" text-anchor="middle" class="d2" style="font-size:6.6px;">Licensed UK</text><text x="167" y="101" text-anchor="middle" class="d2" style="font-size:6.6px;">aerodromes</text><g transform="translate(252 84)"><circle r="44" fill="none" stroke="var(--ink-2)" stroke-width="6" stroke-dasharray="17.5 5.5"/><text x="0" y="-4" text-anchor="middle" class="d3">AIRAC</text><text x="0" y="12" text-anchor="middle" class="d2">every 28 days</text></g><text x="160" y="175" text-anchor="middle" class="d2">Temporary changes: NOTAMs and AIP Supplements</text></g>','GEN for the national framework, ENR for flying between places, AD for aerodromes. Lasting changes come in on fixed AIRAC dates.',320,200)]);
