sec('Avoiding collisions (Skyway Code)','The risk',[dzF('Constant bearing means collision','<g class="pdg"><g opacity="0.35"><g transform="translate(40 170) rotate(70) scale(1)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><g transform="translate(280 40) rotate(225) scale(1)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M40 170L280 40" stroke="var(--bad)" stroke-width="0.8" fill="none" stroke-dasharray="3 3"/></g><g opacity="0.55"><g transform="translate(80 160) rotate(70) scale(1)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><g transform="translate(252 68) rotate(225) scale(1)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M80 160L252 68" stroke="var(--bad)" stroke-width="0.8" fill="none" stroke-dasharray="3 3"/></g><g opacity="0.75"><g transform="translate(120 150) rotate(70) scale(1)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><g transform="translate(224 96) rotate(225) scale(1)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M120 150L224 96" stroke="var(--bad)" stroke-width="0.8" fill="none" stroke-dasharray="3 3"/></g><g opacity="0.9500000000000001"><g transform="translate(160 140) rotate(70) scale(1)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><g transform="translate(196 124) rotate(225) scale(1)"><path d="'+ACPATH+'" fill="var(--ink)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M160 140L196 124" stroke="var(--bad)" stroke-width="0.8" fill="none" stroke-dasharray="3 3"/></g><circle cx="188" cy="128" r="10" fill="none" stroke="var(--bad)" stroke-width="2"/><text x="196" y="150" class="d2">collision point</text><rect x="10" y="10" width="150" height="52" rx="4" fill="var(--surface)" stroke="var(--bad)" stroke-width="1"/><text x="85" y="28" text-anchor="middle" class="d1">Same spot on your</text><text x="85" y="40" text-anchor="middle" class="d1">windscreen and getting</text><text x="85" y="52" text-anchor="middle" class="d1" style="fill:var(--bad)">bigger? Act now</text></g>','A threat that does not move across your windscreen is the one on a collision course. It hardly seems to move until late.',320,200)]);
/* two-ways-to-scan */
sec('Avoiding collisions (Skyway Code)','The visual scan',[dzF('Two ways to scan','<g class="pdg"><path d="M20 150Q160 40 300 150" fill="none" stroke="var(--ink-2)" stroke-width="1"/><circle cx="42" cy="134" r="9" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="42" y="137" text-anchor="middle" class="d2" style="font-size:7px;">1</text><circle cx="56" cy="105" r="9" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="56" y="108" text-anchor="middle" class="d2" style="font-size:7px;">2</text><circle cx="83" cy="81" r="9" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="83" y="84" text-anchor="middle" class="d2" style="font-size:7px;">3</text><circle cx="119" cy="65" r="9" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="119" y="68" text-anchor="middle" class="d2" style="font-size:7px;">4</text><circle cx="160" cy="60" r="9" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="160" y="63" text-anchor="middle" class="d2" style="font-size:7px;">5</text><circle cx="201" cy="65" r="9" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="201" y="68" text-anchor="middle" class="d2" style="font-size:7px;">6</text><circle cx="237" cy="81" r="9" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="237" y="84" text-anchor="middle" class="d2" style="font-size:7px;">7</text><circle cx="264" cy="105" r="9" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="264" y="108" text-anchor="middle" class="d2" style="font-size:7px;">8</text><circle cx="278" cy="134" r="9" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="278" y="137" text-anchor="middle" class="d2" style="font-size:7px;">9</text><text x="160" y="24" text-anchor="middle" class="d2" style="font-size:7.4px;">Side to side: far left, step right in blocks of about 10°</text><text x="160" y="176" text-anchor="middle" class="d2" style="font-size:7.4px;">Pause at least 1 second in each block, then check inside</text><text x="160" y="190" text-anchor="middle" class="d2" style="font-size:7.4px;">Front to side: centre, left, back to centre, then right</text></g>','Your eyes only spot movement when they are still. Spend no more than 25% of your time looking inside.',320,200)]);
/* splitting-the-wind */
sec('Crosswind component (Skyway Code)','Finding the components',[dzF('Splitting the wind','<g class="pdg"><rect x="148" y="40" width="24" height="150" fill="#555c6b"/><text x="160" y="186" text-anchor="middle" class="d2 dk" style="font-size:7px;fill:#fff">RWY</text><path d="M160 50V180" stroke="#fff" stroke-width="1" fill="none" stroke-dasharray="6 5"/><path d="M258.0 6.0L174.4 58.7" stroke="var(--accent)" stroke-width="2.6" fill="none"/><path d="M166.0 64.0L176.8 62.5L172.0 55.0Z" fill="var(--accent)"/><text x="312" y="42" text-anchor="end" class="d1" style="fill:var(--accent)">20 kt, 60° off</text><path d="M166.0 6.0L166.0 49.0" stroke="var(--good)" stroke-width="2" fill="none"/><path d="M166.0 58.0L170.1 49.0L161.9 49.0Z" fill="var(--good)"/><text x="150" y="24" text-anchor="end" class="d2">headwind</text><text x="150" y="36" text-anchor="end" class="d1" style="fill:var(--good)">20 × cos 60 = 10 kt</text><path d="M258.0 64.0L183.0 64.0" stroke="var(--bad)" stroke-width="2" fill="none"/><path d="M174.0 64.0L183.0 68.0L183.0 60.0Z" fill="var(--bad)"/><text x="230" y="84" text-anchor="middle" class="d2">crosswind</text><text x="230" y="96" text-anchor="middle" class="d1" style="fill:var(--bad)">20 × sin 60 ≈ 17 kt</text><path d="M166 64m0-24a24 24 0 0 1 21 12" stroke="var(--ink)" stroke-width="1" fill="none"/><text x="186" y="46" class="d2">60°</text></g>','Crosswind = wind speed × sin(angle). Headwind = wind speed × cos(angle). Past 90°, the headwind becomes a tailwind.',320,200)]);
/* clock-code-rule-of-thumb */
sec('Crosswind component (Skyway Code)','Finding the components',[dzF('Clock code rule of thumb','<g class="pdg"><circle cx="96" cy="116" r="70" fill="var(--surface)" stroke="var(--ink-2)"/><path d="M96 116L131 55" stroke="var(--accent)" stroke-width="1.6" fill="none"/><circle cx="131" cy="55" r="4" fill="var(--accent)"/><text x="139" y="59" class="d1">30°</text><path d="M96 116L145 67" stroke="var(--accent)" stroke-width="1.6" fill="none"/><circle cx="145" cy="67" r="4" fill="var(--accent)"/><text x="153" y="71" class="d1">45°</text><path d="M96 116L157 81" stroke="var(--accent)" stroke-width="1.6" fill="none"/><circle cx="157" cy="81" r="4" fill="var(--accent)"/><text x="165" y="85" class="d1">60°</text><path d="M96 116L166 116" stroke="var(--accent)" stroke-width="1.6" fill="none"/><circle cx="166" cy="116" r="4" fill="var(--accent)"/><text x="174" y="120" class="d1">90°</text><path d="M96 116V46" stroke="var(--ink)" stroke-width="2" fill="none"/><text x="96" y="40" text-anchor="middle" class="d2">runway heading</text><rect x="210" y="40" width="104" height="120" rx="4" fill="var(--surface)" stroke="var(--accent)" stroke-width="1"/><text x="262" y="58" text-anchor="middle" class="d1">Crosswind share</text><text x="226" y="82" class="d1">30°</text><text x="256" y="82" class="d2">half</text><text x="226" y="102" class="d1">45°</text><text x="256" y="102" class="d2">70%</text><text x="226" y="122" class="d1">60°</text><text x="256" y="122" class="d2">85%</text><text x="226" y="142" class="d1">90°</text><text x="256" y="142" class="d2">all of it</text></g>','Quick mental maths: 30° off the runway gives half the wind as crosswind, 60° or more gives nearly all of it.',320,200)]);
/* pave-before-you-go */
sec('Decision making and threat and error management (Skyway Code)','Pre-flight decisions',[dzF('PAVE before you go','<g class="pdg"><rect x="8" y="10" width="148" height="84" rx="8" fill="var(--surface)" stroke="var(--accent)" stroke-width="1.6"/><text x="32" y="50" text-anchor="middle" class="d3" style="font-size:22px;fill:var(--accent)">P</text><text x="52" y="40" class="d1">Pilot</text><text x="52" y="56" class="d2" style="font-size:7px;">recency, fitness</text><text x="52" y="68" class="d2" style="font-size:7px;">I AM SAFE</text><rect x="162" y="10" width="148" height="84" rx="8" fill="var(--surface)" stroke="var(--good)" stroke-width="1.6"/><text x="186" y="50" text-anchor="middle" class="d3" style="font-size:22px;fill:var(--good)">A</text><text x="206" y="40" class="d1">Aircraft</text><text x="206" y="56" class="d2" style="font-size:7px;">airworthiness, limits</text><text x="206" y="68" class="d2" style="font-size:7px;"></text><rect x="8" y="102" width="148" height="84" rx="8" fill="var(--surface)" stroke="var(--mid)" stroke-width="1.6"/><text x="32" y="142" text-anchor="middle" class="d3" style="font-size:22px;fill:var(--mid)">V</text><text x="52" y="132" class="d1">EnVironment</text><text x="52" y="148" class="d2" style="font-size:7px;">weather, aerodrome</text><text x="52" y="160" class="d2" style="font-size:7px;">terrain</text><rect x="162" y="102" width="148" height="84" rx="8" fill="var(--surface)" stroke="var(--bad)" stroke-width="1.6"/><text x="186" y="142" text-anchor="middle" class="d3" style="font-size:22px;fill:var(--bad)">E</text><text x="206" y="132" class="d1">External pressures</text><text x="206" y="148" class="d2" style="font-size:7px;">time, delays</text><text x="206" y="160" class="d2" style="font-size:7px;">passengers</text></g>','The decision to start the flight is often the most important one. Think about the combined effect of the risks.',320,200)]);
/* threat-and-error-management */
sec('Decision making and threat and error management (Skyway Code)','Threat and error management',[dzF('Threat and error management','<g class="pdg"><rect x="8" y="30" width="90" height="120" rx="8" fill="var(--surface)" stroke="var(--mid)" stroke-width="1"/><text x="53" y="50" text-anchor="middle" class="d1">Threats</text><text x="53" y="70" text-anchor="middle" class="d2">weather</text><text x="53" y="84" text-anchor="middle" class="d2">traffic</text><text x="53" y="98" text-anchor="middle" class="d2">short runway</text><text x="53" y="112" text-anchor="middle" class="d2">fatigue</text><path d="M100.0 90.0L107.9 90.0" stroke="var(--ink)" stroke-width="1.4" fill="none"/><path d="M116.0 90.0L107.9 86.4L107.9 93.6Z" fill="var(--ink)"/><rect x="118" y="30" width="90" height="120" rx="8" fill="var(--surface)" stroke="var(--bad)" stroke-width="1"/><text x="163" y="50" text-anchor="middle" class="d1">Errors</text><text x="163" y="70" text-anchor="middle" class="d2">handling</text><text x="163" y="84" text-anchor="middle" class="d2">procedural</text><text x="163" y="98" text-anchor="middle" class="d2">communication</text><path d="M210.0 90.0L217.9 90.0" stroke="var(--ink)" stroke-width="1.4" fill="none"/><path d="M226.0 90.0L217.9 86.4L217.9 93.6Z" fill="var(--ink)"/><rect x="228" y="30" width="86" height="120" rx="8" fill="var(--surface)" stroke="var(--ink)" stroke-width="1"/><text x="271" y="50" text-anchor="middle" class="d1">Undesired</text><text x="271" y="62" text-anchor="middle" class="d1">aircraft state</text><text x="271" y="82" text-anchor="middle" class="d2">attitude</text><text x="271" y="96" text-anchor="middle" class="d2">configuration</text><text x="271" y="110" text-anchor="middle" class="d2">location</text><text x="160" y="172" text-anchor="middle" class="d2">Manage at each stage: plan, anticipate, prioritise,</text><text x="160" y="184" text-anchor="middle" class="d2">remove distractions</text></g>','TEM is defensive flying: spot the threats, trap the errors, and recover before an undesired state becomes an accident.',320,200)]);
/* choosing-a-field-the-six-s */
sec('Emergencies (Skyway Code)','Engine failure',[dzF('Choosing a field: the six S','<g class="pdg"><rect x="8" y="10" width="98" height="84" rx="6" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1"/><text x="57" y="76" text-anchor="middle" class="d1">Wind</text><text x="57" y="88" text-anchor="middle" class="d2" style="font-size:7.2px;">into wind</text><path d="M28.0 46.0L77.0 46.0" stroke="#5aa0d8" stroke-width="2" fill="none"/><path d="M86.0 46.0L77.0 42.0L77.0 50.0Z" fill="#5aa0d8"/><rect x="112" y="10" width="98" height="84" rx="6" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1"/><text x="161" y="76" text-anchor="middle" class="d1">Size</text><text x="161" y="88" text-anchor="middle" class="d2" style="font-size:7.2px;">bigger is better</text><rect x="136" y="24" width="50" height="40" fill="var(--ch-l1)" stroke="var(--good)"/><rect x="216" y="10" width="98" height="84" rx="6" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1"/><text x="265" y="76" text-anchor="middle" class="d1">Surroundings</text><text x="265" y="88" text-anchor="middle" class="d2" style="font-size:7.2px;">power lines, trees</text><path d="M228 30Q265 46 302 30" stroke="var(--ink)" stroke-width="1" fill="none"/><path d="M228 24v40M302 24v40" stroke="var(--ink)" stroke-width="2"/><rect x="8" y="102" width="98" height="84" rx="6" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1"/><text x="57" y="168" text-anchor="middle" class="d1">Shape</text><text x="57" y="180" text-anchor="middle" class="d2" style="font-size:7.2px;">square beats narrow</text><rect x="38" y="116" width="38" height="38" fill="var(--ch-l1)" stroke="var(--good)"/><rect x="112" y="102" width="98" height="84" rx="6" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1"/><text x="161" y="168" text-anchor="middle" class="d1">Surface</text><text x="161" y="180" text-anchor="middle" class="d2" style="font-size:7.2px;">grass over crops</text><rect x="130" y="120" width="30" height="30" fill="var(--ch-l1)"/><rect x="162" y="120" width="30" height="30" fill="#c9a46a"/><path d="M164 126h26M164 134h26M164 142h26" stroke="#8a6a3a" stroke-width="1" fill="none"/><rect x="216" y="102" width="98" height="84" rx="6" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1"/><text x="265" y="168" text-anchor="middle" class="d1">Slope</text><text x="265" y="180" text-anchor="middle" class="d2" style="font-size:7.2px;">avoid it</text><path d="M230 152L300 124" stroke="var(--good)" stroke-width="3" fill="none"/></g>','Wind, size, surroundings, shape, surface and slope. Shortly after take-off, land ahead rather than turning back.',320,200)]);
/* the-constant-aspect-approach */
sec('Emergencies (Skyway Code)','Engine failure',[dzF('The constant aspect approach','<g class="pdg"><rect x="150" y="110" width="70" height="44" fill="var(--ch-l1)" stroke="var(--good)" stroke-width="1.6"/><text x="185" y="136" text-anchor="middle" class="d1">field</text><path d="M60 40Q30 120 90 170Q160 196 200 160" stroke="var(--bad)" stroke-width="2" fill="none" stroke-dasharray="6 3"/><g transform="translate(60 40) rotate(190) scale(1.3)"><path d="'+ACPATH+'" fill="var(--accent)" stroke="var(--surface)" stroke-width=".6" stroke-linejoin="round"/></g><path d="M60 40L160 120" stroke="var(--ink-2)" stroke-width="1" fill="none" stroke-dasharray="3 3"/><text x="118" y="70" class="d1">about 45°</text><text x="250" y="40" text-anchor="middle" class="d1">Keep the angle</text><text x="250" y="52" text-anchor="middle" class="d2">to the field constant</text><text x="250" y="74" text-anchor="middle" class="d2">too high: widen or</text><text x="250" y="85" text-anchor="middle" class="d2">sideslip, S-turn</text><text x="250" y="100" text-anchor="middle" class="d2">too low: tighten</text></g>','Watch the field\'s angle below you and adjust the turn to keep it steady. Aim further in if you will use full flap.',320,200)]);
/* before-you-change-anything */
sec('Emergencies (Skyway Code)','Key principles',[dzF('Before you change anything','<g class="pdg"><circle cx="22" cy="24" r="11" fill="var(--bad)"/><text x="22" y="28" text-anchor="middle" class="d1 dk" style="fill:#fff">1</text><text x="40" y="22" class="d1">Fly the aircraft</text><text x="40" y="33" class="d2">keep a safe flying speed</text><circle cx="22" cy="68" r="11" fill="var(--bad)"/><text x="22" y="72" text-anchor="middle" class="d1 dk" style="fill:#fff">2</text><text x="40" y="66" class="d1">Assess before acting</text><text x="40" y="77" class="d2">do not jump to conclusions</text><circle cx="22" cy="112" r="11" fill="var(--bad)"/><text x="22" y="116" text-anchor="middle" class="d1 dk" style="fill:#fff">3</text><text x="40" y="110" class="d1">Declare early</text><text x="40" y="121" class="d2">easier to cancel than to start late</text><circle cx="22" cy="156" r="11" fill="var(--bad)"/><text x="22" y="160" text-anchor="middle" class="d1 dk" style="fill:#fff">4</text><text x="40" y="154" class="d1">Squawk 7700</text><text x="40" y="165" class="d2">121.5 MHz if not with a unit</text><rect x="232" y="30" width="82" height="120" rx="4" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1"/><text x="273" y="48" text-anchor="middle" class="d1">Lost?</text><text x="273" y="62" text-anchor="middle" class="d2">squawk 0030</text><text x="273" y="74" text-anchor="middle" class="d2">call D&amp;D 121.5</text><text x="273" y="98" text-anchor="middle" class="d1">Radio dead?</text><text x="273" y="112" text-anchor="middle" class="d2">squawk 7600</text><text x="273" y="124" text-anchor="middle" class="d2">stay VMC, watch</text><text x="273" y="136" text-anchor="middle" class="d2">for light signals</text></g>','Many accidents start when a survivable problem distracts the pilot from flying.',320,200)]);
/* fuel-by-volume-and-by-mass */
sec('Fuel, flight plans and aerodrome planning (Skyway Code)','Fuel management',[dzF('Fuel by volume and by mass','<g class="pdg"><path d="M40 40h60l10 14v90a8 8 0 0 1-8 8h-64a8 8 0 0 1-8-8v-90z" fill="var(--surface)" stroke="var(--ink-2)"/><rect x="36" y="90" width="68" height="58" fill="#5aa0d8" opacity=".55"/><text x="70" y="72" text-anchor="middle" class="d1">AVGAS</text><text x="70" y="172" text-anchor="middle" class="d2">0.72 kg per litre</text><path d="M190 40h60l10 14v90a8 8 0 0 1-8 8h-64a8 8 0 0 1-8-8v-90z" fill="var(--surface)" stroke="var(--ink-2)"/><rect x="186" y="90" width="68" height="58" fill="#c9a46a" opacity=".55"/><text x="220" y="72" text-anchor="middle" class="d1">Jet A-1</text><text x="220" y="172" text-anchor="middle" class="d2">about 0.8 kg per litre</text><text x="160" y="24" text-anchor="middle" class="d1">1 US gal = 3.785 L    1 Imp gal = 4.546 L</text><text x="160" y="192" text-anchor="middle" class="d2">For W&B assume fuel high, for planning assume low</text></g>','Mixed units have caused accidents. Match the density to the volume unit and check every figure.',320,200)]);
/* when-you-need-a-flight-plan */
sec('Fuel, flight plans and aerodrome planning (Skyway Code)','Flight plans',[dzF('When you need a flight plan','<g class="pdg"><rect x="14" y="14" width="292" height="24" rx="4" fill="var(--surface)" stroke="var(--accent)" stroke-width="1"/><rect x="14" y="14" width="8" height="24" rx="2" fill="var(--accent)"/><text x="30" y="30" class="d2" style="font-size:7.6px;">Crossing an international border</text><text x="298" y="30" text-anchor="end" class="d1" style="font-size:7.4px;fill:var(--accent)">required</text><rect x="14" y="43" width="292" height="24" rx="4" fill="var(--surface)" stroke="var(--accent)" stroke-width="1"/><rect x="14" y="43" width="8" height="24" rx="2" fill="var(--accent)"/><text x="30" y="59" class="d2" style="font-size:7.6px;">Under an ATC service (into CAS, or from a controlled aerodrome)</text><text x="298" y="59" text-anchor="end" class="d1" style="font-size:7.4px;fill:var(--accent)">required</text><rect x="14" y="72" width="292" height="24" rx="4" fill="var(--surface)" stroke="var(--accent)" stroke-width="1"/><rect x="14" y="72" width="8" height="24" rx="2" fill="var(--accent)"/><text x="30" y="88" class="d2" style="font-size:7.6px;">Leaving the aerodrome vicinity at night</text><text x="298" y="88" text-anchor="end" class="d1" style="font-size:7.4px;fill:var(--accent)">required</text><rect x="14" y="101" width="292" height="24" rx="4" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1"/><rect x="14" y="101" width="8" height="24" rx="2" fill="var(--mid)"/><text x="30" y="117" class="d2" style="font-size:7.6px;">Over water more than 10 NM from the UK coast</text><text x="298" y="117" text-anchor="end" class="d1" style="font-size:7.4px;fill:var(--mid)">recommended</text><rect x="14" y="130" width="292" height="24" rx="4" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1"/><rect x="14" y="130" width="8" height="24" rx="2" fill="var(--mid)"/><text x="30" y="146" class="d2" style="font-size:7.6px;">To the Scottish Highlands and Islands</text><text x="298" y="146" text-anchor="end" class="d1" style="font-size:7.4px;fill:var(--mid)">recommended</text><rect x="14" y="159" width="292" height="24" rx="4" fill="var(--surface)" stroke="var(--ink-2)" stroke-width="1"/><rect x="14" y="159" width="8" height="24" rx="2" fill="var(--mid)"/><text x="30" y="175" class="d2" style="font-size:7.6px;">Over sparsely populated areas</text><text x="298" y="175" text-anchor="end" class="d1" style="font-size:7.4px;fill:var(--mid)">recommended</text></g>','Booking out can count as the abbreviated plan at night if the unit can receive it. Abbreviated plans are not passed on to other units.',320,200)]);
